L["A second game effect over the first."] = "Un second effet du jeu par-dessus le premier."
L["The game's effects slide slowly under their edge."] = "Les effets du jeu glissent lentement sous leur bord."
L["One of the game's full-screen effects closing in as you weaken."] = "Un des effets plein écran du jeu qui se resserre à mesure que vous faiblissez."
L["Turns Vitals Vision on or off."] = "Active ou désactive Vitals Vision."
L["The screen's edges close in as your health drops."] = "Les bords de l'écran se resserrent quand votre vie baisse."
L["How strong the edges are out of a fight."] = "L'intensité des bords hors combat."
L["Ramp up"] = "Montée progressive"
L["Higher makes the edges close in slowly at first, then faster."] = "Plus haut, les bords se resserrent lentement au début, puis plus vite."
L["Replace game's low health flash setting"] = "Remplacer le clignotement de vie basse du jeu"
L["When the game's Do Not Flash Screen at Low Health setting is ticked, the edges don't show."] = "Quand l'option du jeu « Ne pas faire clignoter l'écran si la vie est basse » est cochée, les bords ne s'affichent pas."
