L["Game setting: |cff00ff00flash on|r"] = "Option du jeu : |cff00ff00clignotement activé|r"
L["How fast the edges close in when your health drops."] = "La vitesse à laquelle les bords se resserrent quand votre vie baisse."
L["How fast the edges lift when you're healed."] = "La vitesse à laquelle les bords se dissipent quand vous êtes soigné."
