L["The language Cinematic's text is in; a change needs a reload."] = "La langue des textes de Cinematic ; un changement nécessite un rechargement."
L["The look of Cinematic's settings windows: HD is flat and dark, and SD looks like the game's own."] = "L'apparence des fenêtres d'options de Cinematic : HD est sobre et sombre, SD ressemble à celles du jeu."
L["The game's %s is off"] = "%s du jeu est désactivé"
L["Couldn't turn it on right now; try again after the fight."] = "Impossible de l'activer maintenant ; réessayez après le combat."
L["On. Right-click to turn all its tabs off."] = "Activé. Clic droit pour désactiver tous ses onglets."
L["Off. Right-click to turn all its tabs on."] = "Désactivé. Clic droit pour activer tous ses onglets."
L["Cinematic is about bringing Azeroth to life: your screen changes with the moment you're in, hiding what you don't need and showing what you do."] = "Cinematic donne vie à Azeroth : votre écran change selon le moment que vous vivez, en masquant ce dont vous n'avez pas besoin et en montrant ce qui vous sert."
L["Reset Settings keeps what you made, Reset EVERYTHING deletes it all, and both reload the UI."] = "Réinitialiser les réglages garde ce que vous avez créé, Tout réinitialiser supprime tout, et les deux rechargent l'interface."
L["Effects that play over the world when something happens."] = "Des effets qui se jouent sur le monde quand quelque chose se passe."
L["How the whole interface looks."] = "L'apparence de toute l'interface."
L["Atmosphere"] = "Atmosphère"
L["The camera coming alive."] = "La caméra prend vie."
L["How fast the UI fades, the Calm Timer, and what takes you out of CineMode."] = "La vitesse de fondu de l'interface, le Minuteur de calme, et ce qui vous fait sortir du CineMode."
L["Your interface fades away but comes back when you need it to."] = "Votre interface s'efface mais revient quand vous en avez besoin."
L["Nothing fades right now."] = "Rien ne s'estompe en ce moment."
L["Click to turn CineMode off."] = "Cliquez pour désactiver le CineMode."
L["Click to turn CineMode on."] = "Cliquez pour activer le CineMode."
L["Click to see why."] = "Cliquez pour voir pourquoi."
L["CineMode is on"] = "Le CineMode est activé"
L["CineMode is off"] = "Le CineMode est désactivé"
L["Cameras (Camera tab) is set to CineMode."] = "Caméras (onglet Caméra) est réglé sur CineMode."
L["This page does nothing."] = "Cette page ne fait rien."
L["Works while CineMode is on, and outside it while friendly nameplates show."] = "Fonctionne quand le CineMode est activé, et en dehors tant que les barres de nom alliées s'affichent."
L["Works only while CineMode is on."] = "Ne fonctionne que lorsque le CineMode est activé."
L["Works while CineMode is off too."] = "Fonctionne aussi quand le CineMode est désactivé."
L["This page works as its settings say."] = "Cette page fonctionne selon ses réglages."
L["Click to turn it on or off."] = "Cliquez pour l'activer ou le désactiver."
L["off with %s"] = "désactivé avec %s"
L["How fast the UI fades and what brings it back while CineMode is on."] = "La vitesse de fondu de l'interface et ce qui la fait revenir quand le CineMode est activé."
L["How fast the UI fades, the Calm Timer, and fights coming in."] = "La vitesse de fondu de l'interface, le Minuteur de calme, et l'arrivée des combats."
L["What takes you out of CineMode: fights, places, groups, moving and windows."] = "Ce qui vous fait sortir du CineMode : combats, lieux, groupes, mouvements et fenêtres."
L["The minimap button, /cine hints, language and the menus' look."] = "Le bouton de la minicarte, les suggestions /cine, la langue et l'apparence des menus."
L["How long things take to fade in out of combat."] = "Le temps d'apparition des éléments hors combat."
L["How long things take to fade out."] = "Le temps de disparition des éléments."
L["How long things take to fade in during a fight."] = "Le temps d'apparition des éléments pendant un combat."
L["Casts count too when a rule uses Casting."] = "Les incantations comptent aussi quand une règle utilise Lancer."
L["As soon as a fight ends"] = "Dès la fin d'un combat"
L["How long after a fight before CineMode comes back."] = "Le délai après un combat avant le retour du CineMode."
L["Ends the Calm Timer early once your health and power are back to full."] = "Termine le Minuteur de calme plus tôt une fois votre vie et votre puissance pleines."
L["With a pet out, its health must be full too."] = "Avec un familier invoqué, sa vie doit aussi être pleine."
L["Exit CineMode while an NPC window, like a quest giver or vendor, is open."] = "Quitter le CineMode tant qu'une fenêtre de PNJ, comme un donneur de quêtes ou un marchand, est ouverte."
L["Exit CineMode while a game window, like your bags or the map, is open."] = "Quitter le CineMode tant qu'une fenêtre du jeu, comme vos sacs ou la carte, est ouverte."
L["Picking up an item or spell brings the UI back until you put it down."] = "Prendre un objet ou un sort sur le curseur fait revenir l'interface jusqu'à ce que vous le posiez."
L["How long things must stay calm before CineMode comes back."] = "Combien de temps tout doit rester calme avant le retour du CineMode."
L["Casting at an enemy out of combat brings up your combat frames."] = "Lancer un sort sur un ennemi hors combat affiche vos cadres de combat."
L["Being in combat brings the UI back."] = "Être en combat fait revenir l'interface."
L["In the open world"] = "Dans le monde ouvert"
L["Anywhere outside cities, dungeons and raids."] = "Partout hors des villes, donjons et raids."
L["Capital cities, including Dalaran."] = "Les capitales, Dalaran compris."
L["While you're flagged for PvP out in the world."] = "Tant que vous êtes marqué JcJ dans le monde."
L["In battlegrounds"] = "En champ de bataille"
L["Battlegrounds and arenas."] = "Champs de bataille et arènes."
L["Back after stopping"] = "Retour après l'arrêt"
L["CineMode comes back once you've stood still this long."] = "Le CineMode revient une fois que vous êtes resté immobile ce temps."
L["Back after moving"] = "Retour après le mouvement"
L["CineMode comes back once you've kept moving this long."] = "Le CineMode revient une fois que vous avez bougé sans arrêt ce temps."
L["Allow outside CineMode"] = "Autoriser hors CineMode"
L["CineMode hides your buffs and debuffs: pick what brings them back."] = "Le CineMode masque vos améliorations et affaiblissements : choisissez ce qui les fait revenir."
L["Gaining or refreshing a buff briefly shows your buffs and debuffs."] = "Obtenir ou rafraîchir une amélioration affiche brièvement vos améliorations et affaiblissements."
L["Lets this page bring your hidden buffs and debuffs back in CineMode."] = "Permet à cette page de réafficher vos améliorations et affaiblissements masqués en CineMode."
L["What brings your hidden buffs and debuffs up for a while."] = "Ce qui réaffiche un moment vos améliorations et affaiblissements masqués."
L["Buffs you or your pet cast on yourself don't bring them up."] = "Les améliorations que vous ou votre familier lancez sur vous ne les affichent pas."
L["Not while skyriding"] = "Pas en vol dynamique"
L["No buff brings them up while you're on a skyriding mount."] = "Aucune amélioration ne les affiche tant que vous êtes sur une monture de vol dynamique."
L["Only the buff you gained or refreshed shows."] = "Seule l'amélioration obtenue ou rafraîchie s'affiche."
L["Keep ones lasting less than up until they run out"] = "Garder affichées jusqu'à expiration celles durant moins de"
L["A short buff stays up for as long as it lasts."] = "Une amélioration courte reste affichée tant qu'elle dure."
L["Gaining or refreshing a debuff briefly shows your debuffs."] = "Obtenir ou rafraîchir un affaiblissement affiche brièvement vos affaiblissements."
L["Only within the Calm Timer after a fight."] = "Seulement pendant le Minuteur de calme après un combat."
L["Keeps them up while you have any debuff."] = "Les garde affichés tant que vous avez un affaiblissement."
L["Debuffs that last longer than this don't bring them up."] = "Les affaiblissements qui durent plus longtemps que ceci ne les affichent pas."
L["Override Default Buff Reveal Time"] = "Remplacer la durée d'affichage des améliorations"
L["How long a new buff keeps the buffs up."] = "Combien de temps une nouvelle amélioration garde les améliorations affichées."
L["Override Default Debuff Reveal Time"] = "Remplacer la durée d'affichage des affaiblissements"
L["How long a new debuff keeps the buffs up."] = "Combien de temps un nouvel affaiblissement garde les améliorations affichées."
L["Gaining this doesn't bring your buffs up; type a spell ID or name."] = "Obtenir ceci n'affiche pas vos améliorations ; tapez un ID ou un nom de sort."
L["Keeps drifting to new random distances after the first pull-back."] = "Continue de dériver vers de nouvelles distances aléatoires après le premier recul."
L["How much closer than your own zoom the random zoom may come."] = "De combien le zoom aléatoire peut se rapprocher par rapport à votre propre zoom."
L["How much of each zoom is spent speeding up and slowing down."] = "La part de chaque zoom consacrée à accélérer et ralentir."
L["Each pause varies at random by up to this much."] = "Chaque pause varie aléatoirement jusqu'à cette valeur."
L["Raises the game's max camera distance while pulled back."] = "Augmente la distance maximale de caméra du jeu pendant le recul."
L["Lets the cameras start as the rows below say."] = "Permet aux caméras de démarrer selon les lignes ci-dessous."
L["Top speed in the middle of a sweep."] = "Vitesse maximale au milieu d'un balayage."
L["Each new angle is at least this many degrees from the last."] = "Chaque nouvel angle est éloigné d'au moins ce nombre de degrés du précédent."
L["How far the camera may sway to either side."] = "Jusqu'où la caméra peut se balancer de chaque côté."
L["Each move also tilts the camera to a random angle between these limits."] = "Chaque mouvement incline aussi la caméra à un angle aléatoire entre ces limites."
L["The camera never tilts more than this far below where it started."] = "La caméra ne s'incline jamais plus bas que ceci par rapport à son point de départ."
L["How much of each move is spent speeding up and slowing down."] = "La part de chaque mouvement consacrée à accélérer et ralentir."
L["How long the camera rests between sweeps."] = "Le temps de pause de la caméra entre les balayages."
L["Puts this camera's settings back to your profile's values."] = "Remet les réglages de cette caméra aux valeurs de votre profil."
L["Runs this camera for 30 seconds where you stand."] = "Fait tourner cette caméra 30 secondes là où vous êtes."
L["The camera slowly pulls back, then drifts in and out."] = "La caméra recule lentement, puis dérive en avant et en arrière."
L["After you move the camera yourself, it waits this long before carrying on."] = "Après que vous avez bougé la caméra vous-même, elle attend ce temps avant de continuer."
L["Doing the emote or pressing the sit key."] = "Faire l'emote ou appuyer sur la touche s'asseoir."
L["Clicking Sit, Kneel or Lie down on the campfire card, or its fire button (Emote Vision)."] = "Cliquer sur S'asseoir, S'agenouiller ou S'allonger sur la carte de feu de camp, ou sur son bouton de feu (Emote Vision)."
L["Doing the emote, until you move or jump."] = "Faire l'emote, jusqu'à ce que vous bougiez ou sautiez."
L["Right-clicking a seat to sit on it."] = "Clic droit sur un siège pour s'y asseoir."
L["Unsheathing your weapon with your Sheathe key out of combat."] = "Dégainer votre arme avec votre touche dégainer hors combat."
L["Casting your Hearthstone."] = "Lancer votre pierre de foyer."
L["Casting a teleport spell."] = "Lancer un sort de téléportation."
L["Logging out where the game counts down first."] = "Se déconnecter là où le jeu fait d'abord un compte à rebours."
L["Doing the emote while standing still."] = "Faire l'emote en restant immobile."
L["Casting Fishing, until you move or jump."] = "Lancer Pêche, jusqu'à ce que vous bougiez ou sautiez."
L["Being flagged AFK."] = "Être marqué AFK."
L["Standing still for the time below with nothing else going on."] = "Rester immobile pendant la durée ci-dessous sans rien d'autre en cours."
L["Taking off on a flight path."] = "Décoller sur un trajet aérien."
L["Talking to a quest giver."] = "Parler à un donneur de quêtes."
L["Talking to an NPC about a quest step."] = "Parler à un PNJ d'une étape de quête."
L["On flight paths, the camera sways side to side with an occasional fly-by."] = "Sur les trajets aériens, la caméra se balance de côté et d'autre avec un survol de temps en temps."
L["Your target's frames fade until you pick a new target or land."] = "Les cadres de votre cible s'estompent jusqu'à ce que vous choisissiez une nouvelle cible ou atterrissiez."
L["Sway from side to side"] = "Balancement latéral"
L["The camera sways from side to side around where it started."] = "La caméra se balance de côté et d'autre autour de son point de départ."
L["Your character does /look as a fly-by starts, which players nearby see."] = "Votre personnage fait /look au début d'un survol, ce que voient les joueurs proches."
L["About one fly-by per this many seconds of flight."] = "Environ un survol toutes les tant de secondes de vol."
L["Turn round"] = "Se retourner"
L["Turn back before landing"] = "Revenir avant l'atterrissage"
L["Before you land, the camera turns back to where it was at takeoff."] = "Avant l'atterrissage, la caméra revient à sa position du décollage."
L["Turned back by"] = "Revenue au plus tard"
L["How long before landing the camera has settled."] = "Combien de temps avant l'atterrissage la caméra est stabilisée."
L["When you stand still a while or go AFK, the camera slowly circles your character."] = "Quand vous restez immobile un moment ou passez AFK, la caméra tourne lentement autour de votre personnage."
L["The camera sweeps around your character, pausing between sweeps."] = "La caméra balaye autour de votre personnage, avec des pauses entre les balayages."
L["While you auto-run, the camera follows along until you stop or steer."] = "En course automatique, la caméra suit jusqu'à ce que vous vous arrêtiez ou changiez de direction."
L["The camera eases out a little, then drifts in and out."] = "La caméra recule un peu, puis dérive en avant et en arrière."
L["When you rest, sit or dance, the camera slowly turns to face you and eases in."] = "Quand vous vous reposez, vous asseyez ou dansez, la caméra se tourne lentement face à vous et se rapproche."
L["How far the camera comes down toward the ground as it turns."] = "De combien la caméra descend vers le sol en tournant."
L["The camera eases in close, then drifts a little in and out."] = "La caméra se rapproche, puis dérive un peu en avant et en arrière."
L["The close-up distance the cozy camera zooms in to."] = "La distance de gros plan jusqu'à laquelle zoome la caméra douillette."
L["How much lower the camera sways, to look out across the view."] = "De combien la caméra se balance plus bas, pour embrasser le paysage."
L["The camera eases out a little, then drifts slowly in and out."] = "La caméra recule un peu, puis dérive lentement en avant et en arrière."
L["The camera sways a little from side to side."] = "La caméra se balance un peu de côté et d'autre."
L["How much lower the camera sways, to look out across the water."] = "De combien la caméra se balance plus bas, pour embrasser l'eau."
L["When you die, the camera slowly circles your body until you release or are revived."] = "Quand vous mourez, la caméra tourne lentement autour de votre corps jusqu'à ce que vous libériez votre esprit ou soyez ressuscité."
L["If you die in a boss fight, the death camera waits for it to end."] = "Si vous mourez pendant un combat de boss, la caméra de mort attend sa fin."
L["No death camera when you can come back yourself, like with a soulstone."] = "Pas de caméra de mort quand vous pouvez revenir par vous-même, comme avec une pierre d'âme."
L["Adds a button under the release popup to get your own view back."] = "Ajoute un bouton sous la fenêtre de libération de l'esprit pour retrouver votre vue."
L["How far the camera pulls back while you're dead."] = "De combien la caméra recule pendant que vous êtes mort."
L["How far the camera rises to look down on your body."] = "De combien la caméra s'élève pour regarder votre corps d'en haut."
L["The groups ticked here stay up while the death camera hides your frames."] = "Les groupes cochés ici restent affichés pendant que la caméra de mort masque vos cadres."
L["Music file IDs, separated by commas; one plays at random when you die."] = "ID de fichiers musicaux, séparés par des virgules ; l'un est joué au hasard quand vous mourez."
L["The camera turns toward NPCs as they talk near you."] = "La caméra se tourne vers les PNJ quand ils parlent près de vous."
L["The fastest the camera swings toward a new speaker."] = "La vitesse maximale à laquelle la caméra pivote vers un nouvel interlocuteur."
L["How far from the screen's center the speaker ends up."] = "À quelle distance du centre de l'écran se retrouve celui qui parle."
L["How far the camera drifts side to side once settled."] = "De combien la caméra dérive de côté et d'autre une fois stabilisée."
L["The camera turns around to find speakers you can't see."] = "La caméra se retourne pour trouver les interlocuteurs que vous ne voyez pas."
L["Snaps to speakers, adds a tall letterbox with subtitles and fades the whole UI."] = "Se cale sur les interlocuteurs, ajoute de hautes bandes avec sous-titres et estompe toute l'interface."
L["How fast the camera zooms back out once the talking is over."] = "La vitesse à laquelle la caméra dézoome une fois la conversation terminée."
L["The longest a zoom in or out can take."] = "La durée maximale d'un zoom avant ou arrière."
L["How long no one must talk before the camera turns back."] = "Combien de temps personne ne doit parler avant que la caméra revienne."
L["When you talk to a quest giver, the camera zooms in and looks past you at them."] = "Quand vous parlez à un donneur de quêtes, la caméra zoome et le regarde par-dessus votre épaule."
L["Also zooms in for NPCs with nothing to say about quests."] = "Zoome aussi pour les PNJ qui n'ont rien à dire sur les quêtes."
L["The camera stays put when a quest giver only has dailies or weeklies."] = "La caméra ne bouge pas quand un donneur de quêtes n'a que des journalières ou des hebdomadaires."
L["How far the camera turns to one side to look past you."] = "De combien la caméra tourne sur le côté pour regarder au-delà de vous."
L["How long the turn to the side takes."] = "La durée de la rotation sur le côté."
L["How fast the camera zooms back out once you walk away."] = "La vitesse à laquelle la caméra dézoome une fois que vous vous éloignez."
L["How far the camera comes down toward eye level."] = "De combien la caméra descend vers la hauteur des yeux."
L["When you cast your Hearthstone or a teleport, the camera spins around you as it zooms in."] = "Quand vous lancez votre pierre de foyer ou une téléportation, la caméra tourne autour de vous en zoomant."
L["The distance the zoom ends at as the cast finishes."] = "La distance à laquelle le zoom s'arrête à la fin de l'incantation."
L["Canceling"] = "Annulation"
L["If you cancel the cast, the camera turns back to where it was."] = "Si vous annulez l'incantation, la caméra revient à sa position."
L["Extra settings for cameras that aren't on the Scripts page yet."] = "Réglages supplémentaires pour les caméras qui ne sont pas encore sur la page Scripts."
L["Mouse Turn"] = "Rotation à la souris"
L["Keeps right-mouse turning smooth by capping and easing its speed."] = "Garde la rotation au clic droit fluide en limitant et adoucissant sa vitesse."
L["Cap"] = "Limite"
L["Cap right-click turn speed"] = "Limiter la vitesse de rotation au clic droit"
L["Right-click turning never goes faster than the speed below."] = "La rotation au clic droit ne dépasse jamais la vitesse ci-dessous."
L["Top turn speed"] = "Vitesse de rotation max."
L["The fastest you can turn."] = "La vitesse maximale à laquelle vous pouvez tourner."
L["Ease back over"] = "Retour progressif en"
L["How long your own Mouse Look Speed takes to come back after you slow down."] = "Le temps que met votre propre vitesse de vue à la souris à revenir après un ralentissement."
L["Ramp up right-click turn speed"] = "Accélérer progressivement la rotation au clic droit"
L["Each right-click turn starts slow and builds up to your own speed."] = "Chaque rotation au clic droit commence lentement et monte jusqu'à votre propre vitesse."
L["Start at"] = "Démarrer à"
L["%d%% of your speed"] = "%d%% de votre vitesse"
L["How fast a turn starts, as a share of your own Mouse Look Speed."] = "La vitesse de départ d'une rotation, en part de votre propre vitesse de vue à la souris."
L["Up to full speed over"] = "Pleine vitesse en"
L["How long a turn takes to build up to full speed."] = "Le temps que met une rotation à atteindre sa pleine vitesse."
L["Slow looking up and down too"] = "Ralentir aussi le regard haut/bas"
L["Looking up and down slows by the same share as turning."] = "Regarder vers le haut et le bas ralentit dans la même proportion que la rotation."
L["Turns the whole Atmosphere hub on or off at once."] = "Active ou désactive d'un coup toute la section Atmosphère."
L["How the game world looks in CineMode: vignette, inn glow, weather and depth of field."] = "L'apparence du monde en CineMode : vignette, lueur d'auberge, météo et profondeur de champ."
L["Pick where and when each effect shows in CineMode."] = "Choisissez où et quand chaque effet s'affiche en CineMode."
L["Shows all the time in CineMode, fights included."] = "S'affiche en permanence en CineMode, combats compris."
L["Rain, snow and sandstorms tint the scene, more strongly in heavier weather."] = "La pluie, la neige et les tempêtes de sable teintent la scène, plus fortement quand la météo s'aggrave."
L["Reduce view distance in bad weather"] = "Réduire la distance de vue par mauvais temps"
L["Brings the view distance in during rain, snow or sandstorms, more the heavier it gets."] = "Réduit la distance de vue pendant la pluie, la neige ou les tempêtes de sable, d'autant plus qu'elles sont fortes."
L["The game's graphics settings one by one, shared by every profile on this computer."] = "Les réglages graphiques du jeu un par un, partagés par tous les profils de cet ordinateur."
L["Uses the settings below, or the game's own when turned off."] = "Utilise les réglages ci-dessous, ou ceux du jeu une fois désactivé."
L["World"] = "Monde"
L["Ground clutter, view distance, detail and shadows."] = "Végétation au sol, distance de vue, détails et ombres."
L["Sky and water"] = "Ciel et eau"
L["Clouds, fog, reflections and ripples."] = "Nuages, brouillard, reflets et ondulations."
L["Effects"] = "Effets"
L["Particles, glow, blood and sharpening."] = "Particules, lueur, sang et netteté."
L["HDR"] = "HDR"
L["HDR output and brightness."] = "Sortie HDR et luminosité."
L["Nameplate distance and zoom distance."] = "Distance des barres de nom et distance de zoom."
L["How far away grass and flowers start thinning out."] = "La distance à partir de laquelle l'herbe et les fleurs se raréfient."
L["How far the land is drawn in full; very demanding on frame rate."] = "Jusqu'où le terrain est entièrement affiché ; très exigeant pour les images par seconde."
L["How far away trees, rocks and other objects keep their full detail."] = "Jusqu'à quelle distance les arbres, rochers et autres objets gardent tous leurs détails."
L["How far away small objects stay before they fade out."] = "Jusqu'à quelle distance les petits objets restent visibles avant de disparaître."
L["How far away creatures and characters keep their full detail."] = "Jusqu'à quelle distance les créatures et personnages gardent tous leurs détails."
L["How far away nameplates show, in yards."] = "La distance d'affichage des barres de nom, en mètres."
L["How far out you can zoom the camera."] = "Jusqu'où vous pouvez dézoomer la caméra."
L["Higher gives sharper shadow edges, lower saves frame rate."] = "Plus haut donne des ombres plus nettes, plus bas économise des images par seconde."
L["Horizon distance"] = "Distance de l'horizon"
L["How far the flat horizon past the land reaches."] = "Jusqu'où s'étend l'horizon plat au-delà du terrain."
L["Sky detail"] = "Détail du ciel"
L["How detailed the clouds and sky are."] = "Le niveau de détail des nuages et du ciel."
L["Volumetric fog"] = "Brouillard volumétrique"
L["Fog with depth in place of the usual distance fog."] = "Un brouillard avec de la profondeur à la place du brouillard de distance habituel."
L["Water reflections"] = "Reflets de l'eau"
L["How much of the world water reflects."] = "La part du monde que l'eau reflète."
L["Water ripples"] = "Ondulations de l'eau"
L["How detailed the ripples on water are."] = "Le niveau de détail des ondulations sur l'eau."
L["Particle density"] = "Densité des particules"
L["How many particles spells and effects show."] = "Le nombre de particules affichées par les sorts et effets."
L["Full-screen glow"] = "Lueur plein écran"
L["A soft glow around bright light."] = "Une douce lueur autour des lumières vives."
