L["Restarts the game's graphics without leaving the game; the screen goes black for a moment."] = "Redémarre les graphismes du jeu sans quitter le jeu ; l'écran devient noir un instant."
L["Sound and music during CineMode; your own sound settings come back afterward."] = "Le son et la musique pendant le CineMode ; vos propres réglages de son reviennent ensuite."
L["Plays music when a camera starts in CineMode and fades it out when the UI returns."] = "Joue de la musique quand une caméra démarre en CineMode et l'estompe au retour de l'interface."
L["Pick where and when music can play in CineMode."] = "Choisissez où et quand la musique peut jouer en CineMode."
L["After a camera starts music, no camera starts it again for this long."] = "Après qu'une caméra a lancé la musique, aucune caméra ne la relance pendant ce temps."
L["Fades music out once you leave the camera modes and move on."] = "Estompe la musique une fois que vous quittez les modes de caméra et repartez."
L["Each row is a scene that plays its camera when one of its triggers happens."] = "Chaque ligne est une scène qui joue sa caméra quand un de ses déclencheurs se produit."
L["Lets the scenes below play their cameras when their triggers happen."] = "Permet aux scènes ci-dessous de jouer leurs caméras quand leurs déclencheurs se produisent."
L["Auto-running in walk mode."] = "Course automatique en mode marche."
L["Auto-running."] = "Course automatique."
L["Dying, until you release or are resurrected."] = "Mourir, jusqu'à ce que vous libériez votre esprit ou soyez ressuscité."
L["An NPC talking to you or your party; the camera swings toward whoever's talking."] = "Un PNJ qui vous parle ou parle à votre groupe ; la caméra pivote vers celui qui parle."
L["Other NPCs talking near you, once you've stood still a while."] = "D'autres PNJ qui parlent près de vous, une fois que vous êtes resté immobile un moment."
