L["Plays a song of its own while the death camera runs."] = "Joue sa propre musique pendant que la caméra de mort tourne."
L["Brings CineMode on while this camera runs, when Start in CineMode is off."] = "Active le CineMode pendant que cette caméra tourne, quand Démarrer en CineMode est désactivé."
