L["Words in an object's name that mark it as a seat, separated by commas."] = "Les mots du nom d'un objet qui en font un siège, séparés par des virgules."
L["How long you stand still before this row's camera starts."] = "Combien de temps vous restez immobile avant que la caméra de cette ligne démarre."
L["How long the camera waits on a quest window before it starts."] = "Combien de temps la caméra attend sur une fenêtre de quête avant de démarrer."
L["How long the camera waits on the window before it starts."] = "Combien de temps la caméra attend sur la fenêtre avant de démarrer."
L["How long you stand still before NPCs chatting nearby start this camera."] = "Combien de temps vous restez immobile avant que des PNJ qui discutent à proximité lancent cette caméra."
