L["Pick Always, < 100% or Off, or scroll over the box for other percentages."] = "Choisissez Toujours, < 100 % ou Désactivé, ou faites défiler la molette sur la case pour d'autres pourcentages."
L["Turns this page on or off, same as right-clicking its icon."] = "Active ou désactive cette page, comme un clic droit sur son icône."
L["Put this page's settings back to your profile's defaults?"] = "Remettre les réglages de cette page aux valeurs par défaut de votre profil ?"
L["Put these settings back to your profile's defaults?"] = "Remettre ces réglages aux valeurs par défaut de votre profil ?"
L["|cff808080Searching...|r"] = "|cff808080Recherche...|r"
L["Allow offscreen nameplates in CineMode"] = "Barres de nom hors écran en CineMode"
L["Keeps plates for people behind you, so Heal Vision and Emote Vision see them too."] = "Garde les barres des gens derrière vous, pour que Heal Vision et Emote Vision les voient aussi."
L["Only where Heal Vision or Emote Vision use them."] = "Seulement là où Heal Vision ou Emote Vision s'en servent."
L["All through CineMode."] = "Pendant tout le CineMode."
L["Cinematic never turns them on."] = "Cinematic ne les active jamais."
L["CineMode turns on by itself between fights and fades the UI."] = "Le CineMode s'active tout seul entre les combats et estompe l'interface."
L["Walking or riding around brings the UI back."] = "Marcher ou chevaucher fait revenir l'interface."
L["Use a Show in row instead"] = "Utiliser une ligne Afficher dans"
L["The row below picks where CineMode exits, in place of the boxes above."] = "La ligne ci-dessous choisit où le CineMode se quitte, à la place des cases du dessus."
L["Keeps CineMode off everywhere."] = "Garde le CineMode désactivé partout."
L["Sweeps turn the other way."] = "Les balayages tournent dans l'autre sens."
L["Each time, the camera picks clockwise or counterclockwise at random."] = "À chaque fois, la caméra tourne au hasard dans un sens ou dans l'autre."
L["Put this camera's settings back to your profile's defaults?"] = "Remettre les réglages de cette caméra aux valeurs par défaut de votre profil ?"
L["Now and then the camera turns around to look back past you."] = "De temps en temps, la caméra se retourne pour regarder derrière vous."
L["How far the camera turns around, where 180 looks straight back at you."] = "De combien la caméra se retourne : à 180, elle vous regarde bien en face."
L["How long the turn around takes, speeding up and slowing down."] = "La durée du demi-tour, en accélérant puis en ralentissant."
L["As you land, the camera zooms back to the zoom you had at takeoff."] = "À l'atterrissage, la caméra revient au zoom que vous aviez au décollage."
L["The camera sways slowly from side to side around where it started, pausing between moves."] = "La caméra se balance lentement d'un côté à l'autre autour de son point de départ, avec des pauses entre chaque mouvement."
L["Once it has turned halfway around, the camera sways slowly from side to side."] = "Une fois à mi-tour, la caméra se balance lentement d'un côté à l'autre."
L["When you /stare at the view, the camera sways very slightly from where it is."] = "Quand vous faites /stare devant la vue, la caméra se balance très légèrement là où elle est."
L["The camera sways very slightly from side to side."] = "La caméra se balance très légèrement d'un côté à l'autre."
L["While you fish, the camera sways a little and keeps your bobber in view."] = "Pendant que vous pêchez, la caméra se balance un peu et garde votre flotteur en vue."
L["While you auto-walk, the camera drifts slowly along with you."] = "En marche automatique, la caméra glisse doucement avec vous."
L["Each death, the camera picks clockwise or counterclockwise at random."] = "À chaque mort, la caméra tourne au hasard dans un sens ou dans l'autre."
L["The camera zooms in to this distance if you're farther out."] = "La caméra se rapproche jusqu'à cette distance si vous êtes plus loin."
L["Which side of you the camera moves to."] = "De quel côté de vous la caméra se place."
L["The camera turns to the side as it zooms in, then tilts down."] = "La caméra tourne sur le côté en se rapprochant, puis s'incline vers le bas."
L["How fast the spin speeds up after the first half turn."] = "La vitesse à laquelle la rotation accélère après le premier demi-tour."
L["As it turns, the camera also drops toward the ground. Negative values raise it instead."] = "En tournant, la caméra descend aussi vers le sol. Une valeur négative la fait monter."
L["The camera starts zooming in when the cast starts, and is still zooming in as you leave."] = "La caméra commence à se rapprocher au début de l'incantation, et se rapproche encore quand vous partez."
L["How fast the camera zooms back out to your own distance if you cancel the cast."] = "La vitesse à laquelle la caméra revient à votre distance si vous annulez l'incantation."
L["Load Atmosphere"] = "Charger Atmosphère"
L["Unticked, Atmosphere doesn't load at all (takes a reload)."] = "Décoché, Atmosphère ne se charge pas du tout (après un rechargement)."
L["Tick it and reload to bring every Atmosphere page back."] = "Cochez-le et rechargez pour retrouver toutes les pages d'Atmosphère."
L["Turn off to keep Atmosphere from loading at all."] = "Désactivez pour qu'Atmosphère ne se charge pas du tout."
L["Atmosphere isn't loaded: no tint, letterbox, haze, Graphics Boost or music runs, and their pages are gone."] = "Atmosphère n'est pas chargé : pas de teinte, de bandes, de brume, de Boost graphique ni de musique, et leurs pages ont disparu."
L["How the game world looks in CineMode: vignette, inn glow and depth of field."] = "L'apparence du monde en CineMode : vignette, lueur d'auberge et profondeur de champ."
L["Haze"] = "Brume"
L["Darkens the edges of the screen."] = "Assombrit les bords de l'écran."
L["Shows the vignette for a few seconds, in CineMode or not."] = "Affiche la vignette quelques secondes, en CineMode ou non."
L["A warm firelight glow, brightest low on the screen."] = "Une chaude lueur de feu, plus forte en bas de l'écran."
L["Shows the glow for a few seconds, in CineMode or not."] = "Affiche la lueur quelques secondes, en CineMode ou non."
L["Haze strength"] = "Intensité de la brume"
L["A light haze around the edges of the screen."] = "Une légère brume autour des bords de l'écran."
L["Shows the haze at this strength for a few seconds, in CineMode or not."] = "Affiche la brume à cette intensité quelques secondes, en CineMode ou non."
L["How they look"] = "Leur apparence"
L["Style pages:"] = "Pages Style :"
L["The tint's preset, time of day and zone moods."] = "Le préréglage de la teinte, le moment de la journée et l'ambiance des zones."
L["Each weather's color, and how fast it comes in."] = "La couleur de chaque météo, et la vitesse à laquelle elle arrive."
L["Music can play any time in CineMode, so the other columns don't matter."] = "La musique peut jouer à tout moment en CineMode, les autres colonnes ne comptent donc pas."
L["Load Cameras"] = "Charger les caméras"
L["Unticked, Cinematic's cameras don't load at all (takes a reload)."] = "Décoché, les caméras de Cinematic ne se chargent pas du tout (après un rechargement)."
L["Tick it and reload to bring every camera back."] = "Cochez-le et rechargez pour retrouver toutes les caméras."
L["Turn off to keep the cameras from loading at all."] = "Désactivez pour que les caméras ne se chargent pas du tout."
L["Cameras aren't loaded: none of them run, and their pages are gone."] = "Les caméras ne sont pas chargées : aucune ne fonctionne, et leurs pages ont disparu."
L["In CineMode, the camera moves on its own when things happen, like emotes, flights or going AFK."] = "En CineMode, la caméra bouge toute seule quand il se passe quelque chose : emotes, vols, passage AFK..."
