L["When the XP bar, bags, micro menu and similar frames show."] = "Quand s'affichent la barre d'XP, les sacs, le micro-menu et les cadres du genre."
L["How the damage and healing numbers over heads look."] = "L'apparence des chiffres de dégâts et de soins au-dessus des têtes."
L["Shows chat bubbles where this page says. When it's off, the game's own settings are used."] = "Affiche les bulles de discussion là où le dit cette page. Désactivée, ce sont les réglages du jeu qui comptent."
