L[" Hostile NPCs and enemy players within about 30 yards (your spell nearest 30 yards), whatever their rows say."] = " Les PNJ hostiles et les joueurs ennemis à environ 30 m (votre sort le plus proche de 30 m), quoi que disent leurs lignes."
