L["Pointing at a faded frame shows it, along with the other frames in its groups."] = "Pointer un cadre estompé l'affiche, avec les autres cadres de ses groupes."
L["Right-click to go back to its own icon."] = "Clic droit pour revenir à sa propre icône."
L["Floating text changes after you log out and back in (/reload isn't enough). The same goes for getting it back: until you log out it stays hidden, even with Cinematic turned off."] = "Le texte flottant change après une déconnexion puis reconnexion (/reload ne suffit pas). Pareil pour le récupérer : tant que vous ne vous déconnectez pas, il reste masqué, même avec Cinematic désactivé."
L["Style isn't loaded: no Style page or look runs, and their pages are gone."] = "Style n'est pas chargé : aucune page Style ni apparence ne fonctionne, et leurs pages ont disparu."

-- ProfilerPage.lua
L["It's off. Right-click the Profiler icon to start sampling."] = "Il est désactivé. Clic droit sur l'icône du Profiler pour lancer les mesures."
L["What the game measured for Cinematic over the same time, including what the timers don't cover."] = "Ce que le jeu a mesuré pour Cinematic sur la même durée, y compris ce que les minuteurs ne couvrent pas."
L["Memory used and thrown away each second. The game spends time cleaning it up."] = "La mémoire utilisée puis jetée chaque seconde. Le jeu passe du temps à la nettoyer."
L["(Called by the part above, so its time is counted in that one.)"] = "(Appelé par la partie du dessus, donc son temps est compté dans celle-ci.)"

