L["open now"] = "ouverte"

-- Slash.lua
L["the camera turns once around you: 360 degrees over 10 seconds unless you give a number (a negative one turns the other way); again stops it"] = "la caméra fait un tour autour de vous : 360 degrés en 10 secondes, sauf si vous donnez un nombre (négatif pour tourner dans l'autre sens) ; à nouveau pour l'arrêter"
L["show or hide the keyboard map: what each of your keys does (add words to find them on it)"] = "afficher ou masquer la carte du clavier : ce que fait chacune de vos touches (ajoutez des mots pour les y trouver)"
L["fade the frame you're hovering over too (or /cine add <FrameName>)"] = "estomper aussi le cadre que vous survolez (ou /cine add <NomDuCadre>)"
L["your damage report for this run: boss by boss, the rest, the whole party (test shows a made-up one)"] = "votre rapport de dégâts pour cette expédition : boss par boss, le reste, tout le groupe (test en montre un inventé)"
L["record what the addon costs, results on the Profiler page (add deep for more detail, or stop to end it early)"] = "enregistrer ce que coûte l'addon, résultats sur la page Profiler (ajoutez deep pour plus de détails, ou stop pour arrêter avant)"
