-- Atmosphere/LowHealth.lua
L["That isn't the whole thing. Copy it again, all of it."] = "Ce n'est pas complet. Copiez-le à nouveau, en entier."
L["At what health the edges close in, and how fast."] = "À quel niveau de vie les bords se resserrent, et à quelle vitesse."
L["The color of a big hit's flash, and the color the world fades to."] = "La couleur du flash d'un gros coup, et celle vers laquelle le monde s'estompe."
L["This theme's heartbeat speed, relative to Beats a minute above. A creeping theme beats slower."] = "La vitesse du battement de cœur de ce thème, par rapport aux Battements par minute du dessus. Un thème rampant bat plus lentement."
L["How much this theme throbs, relative to Throb above."] = "À quel point ce thème pulse, par rapport à Pulsation au-dessus."
L["The theme's art that spreads in from the edges."] = "L'illustration du thème qui s'étend depuis les bords."
L["The glow around the art, added as light. This is Glow's only color."] = "La lueur autour de l'illustration, ajoutée comme de la lumière. C'est la seule couleur de Lueur."
L["How strong the glow is compared to the art."] = "La force de la lueur par rapport à l'illustration."
L["The theme's art (blood, smoke, a glow) that spreads in from the edges as they close in."] = "L'illustration du thème (sang, fumée, lueur) qui s'étend depuis les bords à mesure qu'ils se resserrent."
L["How many appear per minute at full strength. A big hit adds a few more."] = "Combien en apparaissent par minute à pleine intensité. Un gros coup en ajoute quelques-uns."
L["How big they are compared to normal."] = "Leur taille par rapport à la normale."
L["How strong it is at full, multiplied by the art's opacity."] = "Sa force au maximum, multipliée par l'opacité de l'illustration."
L["Overall strength, reach and brightness, plus the shadow, the heartbeat and big hits."] = "Intensité générale, portée et luminosité, plus l'ombre, le battement de cœur et les gros coups."
L["How the screen looks as your mana runs out."] = "L'apparence de l'écran quand votre mana s'épuise."
L["As your health drops, the edges of the screen close in."] = "Quand votre vie baisse, les bords de l'écran se resserrent."
L["Shows everywhere, so the other columns don't change anything."] = "S'affiche partout, les autres colonnes ne changent donc rien."
L["The edges start closing in when your health drops below this."] = "Les bords commencent à se resserrer quand votre vie passe sous ce seuil."
L["The edges are all the way in when your health drops to this. Keep it below Starts."] = "Les bords sont complètement resserrés quand votre vie tombe à ce seuil. Gardez-le sous Début."
L["How much of your health one hit has to take to count as a big hit."] = "La part de votre vie qu'un coup doit retirer pour compter comme un gros coup."
L["As your mana runs out, the screen drains. Right-click the tab to turn it on."] = "Quand votre mana s'épuise, l'écran se vide de ses couleurs. Clic droit sur l'onglet pour l'activer."

-- Atmosphere/ManaVision.lua
L["Low mana"] = "Mana basse"
