L["The screen is fully drained when your mana drops to this. Keep it below Starts."] = "L'écran est complètement vidé quand votre mana tombe à ce seuil. Gardez-le sous Début."
L["How strong it is out of a fight."] = "Sa force hors combat."
L["Shows your mana running out on the screen."] = "Montre à l'écran votre mana qui s'épuise."
L["This character doesn't use mana, so nothing shows."] = "Ce personnage n'utilise pas de mana, rien ne s'affiche donc."
L["Drained"] = "Délavé"
L["Gray-blue: the world's color drains away."] = "Gris-bleu : les couleurs du monde s'en vont."
L["Cold"] = "Froid"
L["A cold, deep blue."] = "Un bleu froid et profond."
L["A dim, gray-violet dusk."] = "Un crépuscule sombre, gris-violet."
L["How strong the veil and the edges are when your mana is out."] = "La force du voile et des bords quand vous n'avez plus de mana."
L["Dark edges"] = "Bords sombres"
L["Dark edges close in as your mana runs out."] = "Des bords sombres se resserrent quand votre mana s'épuise."
L["How far in from the screen's edges they come."] = "Jusqu'où ils s'avancent depuis les bords de l'écran."
L["Shows your mana running out in the preview and on screen."] = "Montre votre mana qui s'épuise dans l'aperçu et à l'écran."

-- Atmosphere/TeleportVision.lua
L["Motes in the portal's color drift in from the rim."] = "Des particules de la couleur du portail arrivent depuis son bord."
L["Plays a pretend 8-second cast on screen. Close the settings to see it."] = "Joue à l'écran une fausse incantation de 8 secondes. Fermez les options pour la voir."

-- Atmosphere/Tint.lua
L["Warm brownish yellow, like an old photo. The world can't be fully desaturated."] = "Jaune brun chaud, comme une vieille photo. Le monde ne peut pas être complètement désaturé."
L["A warm haze over everything."] = "Une brume chaude sur tout."

-- Camera/CameraManager.lua
L["Right-click to copy it, or to rename, describe, change the icon of or delete one of yours."] = "Clic droit pour la copier, ou pour renommer, décrire, changer l'icône ou supprimer une des vôtres."
L["Makes a copy of this camera's script for you to change, and opens its tab."] = "Fait une copie du script de cette caméra pour que vous la modifiiez, et ouvre son onglet."

-- Camera/CameraScriptsPage.lua
L["Runs when the camera ends, whatever ends it (its stop rules say what does). Every camera has one and it can't be removed. Pick it and add steps to put them inside."] = "Se lance quand la caméra se termine, quelle qu'en soit la raison (ses règles d'arrêt disent laquelle). Chaque caméra en a un et on ne peut pas l'enlever. Choisissez-le et ajoutez des étapes pour les mettre dedans."
L["Lets scenes play your scripts, and lets our cameras use your changes to their scripts."] = "Permet aux scènes de jouer vos scripts, et à nos caméras d'utiliser vos modifications de leurs scripts."
L["This script as text to share with friends."] = "Ce script en texte, à partager avec des amis."
L["A haze around the edges of the screen while this camera runs. Set to 0 to turn it off."] = "Une brume autour des bords de l'écran pendant cette caméra. Réglez sur 0 pour la désactiver."
L["A built-in camera you've changed. Reset puts ours back."] = "Une caméra intégrée que vous avez modifiée. Réinitialiser remet la nôtre."
L["A built-in camera, made from your settings. Any change you make saves it as your own."] = "Une caméra intégrée, faite à partir de vos réglages. Toute modification l'enregistre comme la vôtre."

-- Camera/CameraTriggerEditor.lua
L["Another trigger for this scene. Any one of its triggers starts it."] = "Un autre déclencheur pour cette scène. N'importe lequel de ses déclencheurs la lance."
L["Turns CineMode on while its camera runs, if Start in CineMode is off."] = "Active le CineMode pendant sa caméra, si Démarrer en CineMode est désactivé."

-- Camera/ShotsPage.lua
L["Copies text you can send a friend, who adds this shot with Import here or on their Scenes page."] = "Copie un texte à envoyer à un ami, qui ajoute ce plan avec Importer ici ou sur sa page Scènes."
L["The camera whose moves this shot uses."] = "La caméra dont ce plan utilise les mouvements."
L["Clears this shot's numbers so they go back to its camera's own settings."] = "Efface les valeurs de ce plan pour revenir aux réglages de sa caméra."

-- Camera/ShoulderCalibrate.lua
L["Stops using this measurement and goes back to the built-in size."] = "Arrête d'utiliser cette mesure et revient à la taille intégrée."

-- Camera/ShoulderCam.lua
L["Another addon (DynamicCam) is running a shoulder camera, so the Shoulder Cam stays off."] = "Un autre addon (DynamicCam) gère déjà une caméra d'épaule, la Caméra d'épaule reste donc désactivée."
L["Shoulder Cam uses some experimental Blizzard features, as well as some hacks to fill in the gaps."] = "La Caméra d'épaule utilise des fonctions expérimentales de Blizzard, plus quelques astuces pour combler les trous."
L["Which frames slide with you while the camera is over your shoulder."] = "Quels cadres glissent avec vous quand la caméra est sur votre épaule."
L["Which of Cinematic's cameras keep the Shoulder Cam on while they play."] = "Quelles caméras de Cinematic gardent la Caméra d'épaule active pendant qu'elles jouent."
L["Over your shoulder everywhere, so the other columns don't matter."] = "Sur l'épaule partout, les autres colonnes ne comptent donc pas."
L["How far from the middle you sit when zoomed out. Set it lower than Spot on screen to keep the camera from catching on walls, which only happens zoomed out."] = "À quelle distance du centre vous êtes une fois dézoomé. Réglez-le plus bas que Place à l'écran pour que la caméra n'accroche pas les murs, ce qui n'arrive qu'en dézoom."
L["The camera distance where you reach Spot zoomed out. Between 5 yards and this distance, you slide from Spot on screen to Spot zoomed out."] = "La distance de caméra où vous atteignez Position en dézoom. Entre 5 m et cette distance, vous glissez de Place à l'écran à Position en dézoom."
L["Keep the shoulder when selecting yourself"] = "Garder l'épaule en vous ciblant"
L["Selecting yourself clears your target instead, so the camera stays over your shoulder. Heals and buffs still land on you."] = "Vous cibler efface plutôt votre cible, pour que la caméra reste sur votre épaule. Soins et améliorations vous atteignent quand même."
L["Shows our own copy of your target frame, so it matches only the game's look or a Cinematic theme."] = "Affiche notre propre copie de votre cadre de cible, pour qu'il suive seulement l'apparence du jeu ou un thème Cinematic."
L["How long the Shoulder Cam waits to come back over your shoulder after you step outside or get off your mount. Going back in or mounting again during the wait starts it over."] = "Combien de temps la Caméra d'épaule attend avant de revenir sur votre épaule quand vous sortez ou descendez de monture. Rentrer ou remonter pendant l'attente la relance à zéro."
L["Turns to who you talk to everywhere, so the other columns don't matter."] = "Se tourne vers votre interlocuteur partout, les autres colonnes ne comptent donc pas."
L["How many seconds the camera takes to move behind you for this camera. Leave it empty to use %s."] = "Combien de secondes la caméra met à passer derrière vous pour cette caméra. Laissez vide pour utiliser %s."

-- Camera/SkyrideCam.lua
L["Everywhere you skyride, so the other columns don't matter."] = "Partout où vous êtes en vol dynamique, les autres colonnes ne comptent donc pas."
L["How far past your cruise distance (set in Take off) the camera goes."] = "Jusqu'où la caméra va au-delà de votre distance de croisière (réglée dans Décollage)."
L["At 0.5 it's a snap, as fast as the game's zoom can go."] = "À 0.5, c'est instantané, aussi vite que le zoom du jeu le permet."
L["How close the camera comes in. Set to 0 to keep its distance."] = "À quel point la caméra se rapproche. Réglez sur 0 pour garder sa distance."
L["Second Wind brings the camera in a little, then back out."] = "Second souffle rapproche un peu la caméra, puis l'éloigne de nouveau."
L["The fastest the camera can move. Moves that would go faster take longer instead."] = "La vitesse max de la caméra. Les mouvements qui iraient plus vite prennent plus de temps à la place."
L["Blends one move into the next. At 0 the camera stops between moves."] = "Enchaîne un mouvement dans le suivant. À 0, la caméra s'arrête entre deux mouvements."

-- Camera/TriggersPage.lua
L["For now, its camera follows its own rules for when it plays."] = "Pour l'instant, sa caméra suit ses propres règles pour savoir quand jouer."
L["Moves it up, so it wins over the one above."] = "Le monte, pour qu'il passe avant celui du dessus."
L["Moves it down, so the one below wins over it."] = "Le descend, pour que celui du dessous passe avant lui."
L["Makes a copy of this trigger that you can change on its own."] = "Fait une copie de ce déclencheur que vous pouvez modifier séparément."
L["Puts its Only if, wait, cooldown, chance and priority back to how they came."] = "Remet son Seulement si, son attente, son temps de recharge, sa chance et sa priorité comme au départ."
L["A wait before it starts, a minimum time, a cooldown and a chance."] = "Une attente avant de démarrer, une durée minimum, un temps de recharge et une chance."
L["A rule that must be true for it to start. Leave it empty to always start. Click to edit."] = "Une règle qui doit être vraie pour qu'il démarre. Laissez vide pour toujours démarrer. Cliquez pour modifier."
L["When on, it waits until its condition is no longer true before it can start again."] = "Activé, il attend que sa condition ne soit plus vraie avant de pouvoir redémarrer."

