-- Style/BubbleStyle.lua
L["Just the words, with no bubble. An outline makes them easier to read."] = "Juste les mots, sans bulle. Un contour les rend plus faciles à lire."
L["How big speech from behind you is compared to a bubble overhead. Smaller makes it seem farther away."] = "La taille des paroles venant de derrière vous, comparée à une bulle au-dessus d'une tête. Plus petit, ça semble plus loin."
L["How solid speech from behind you looks. Fainter makes it seem muffled and out of view."] = "À quel point les paroles venant de derrière vous sont nettes. Plus pâle, ça semble étouffé et hors de vue."

-- Style/CdmStyle.lua
L["After a few hits"] = "Après quelques coups"
L["Draining"] = "Se vide"
L["Just cast"] = "Tout juste lancé"
L["Halfway"] = "À moitié"
L["Cooldown Manager Style"] = "Style du gestionnaire de recharges"
L["How the drain ring on your tracked buffs looks. Pick which buffs get one on the Cooldown Manager page, under Look."] = "L'apparence de l'anneau qui se vide sur vos améliorations suivies. Choisissez lesquelles en ont un sur la page Gestionnaire de recharges, sous Apparence."
L["Turns this page's ring look on or off. Off: the ring's own look."] = "Active ou désactive l'apparence d'anneau de cette page. Désactivé : l'apparence de base de l'anneau."
L["How the drain ring on your tracked buffs looks."] = "L'apparence de l'anneau qui se vide sur vos améliorations suivies."
L["The Cooldown Manager icons' shape."] = "La forme des icônes du gestionnaire de recharges."
L["Cooldown + DoT"] = "Recharge + DoT"
L["How a spell's cooldown shows over its DoT, on rows whose Shows is Both."] = "Comment la recharge d'un sort s'affiche par-dessus son DoT, sur les lignes dont l'Affichage est Les deux."
L["The icons take Action Bar Style's shape."] = "Les icônes prennent la forme de Style des barres d'action."
L["Square icons, whatever the action buttons are."] = "Des icônes carrées, quels que soient les boutons d'action."
L["Round icons, whatever the action buttons are."] = "Des icônes rondes, quels que soient les boutons d'action."
L["Pips"] = "Pastilles"
L["Eight chunky segments round the icon."] = "Huit gros segments autour de l'icône."
L["One thin ring round the icon."] = "Un anneau fin autour de l'icône."
L["Liquid"] = "Liquide"
L["The icon empties from the top down."] = "L'icône se vide de haut en bas."
L["Bar under"] = "Barre dessous"
L["A thin bar under the icon."] = "Une fine barre sous l'icône."
L["How big the ring is next to the icon."] = "La taille de l'anneau par rapport à l'icône."
L["Empty part"] = "Partie vide"
L["How dark the spent part shows. 0: hidden."] = "À quel point la partie écoulée est sombre. 0 : masquée."
L["The ring in your class's color."] = "L'anneau à la couleur de votre classe."
L["From the full end's color to the empty end's: what's left turns toward the empty color as it drains."] = "De la couleur du bout plein à celle du bout vide : ce qui reste tire vers la couleur vide à mesure que ça se vide."
L["The color you pick below."] = "La couleur choisie ci-dessous."
L["A plain white ring."] = "Un simple anneau blanc."
