L["Empty end"] = "Bout vide"
L["The gradient's color where the shield runs out."] = "La couleur du dégradé là où le bouclier s'épuise."
L["Left / right"] = "Gauche / droite"
L["Moves the amount left or right from the icon's middle."] = "Déplace la valeur à gauche ou à droite du centre de l'icône."
L["Down / up"] = "Bas / haut"
