L["How big the amount's text is."] = "La taille du texte de la valeur."
L["Which buffs get a ring, and the game's timer: the Cooldown Manager page, under Look."] = "Quelles améliorations ont un anneau, et le minuteur du jeu : page Gestionnaire de recharges, sous Apparence."
L["Pips in a ring round the icon."] = "Des pastilles en anneau autour de l'icône."
L["Edge pips"] = "Pastilles au bord"
