L["Which spells show both: the Cooldown Manager page, Look, Shows."] = "Quels sorts affichent les deux : page Gestionnaire de recharges, Apparence, Affichage."

-- Style/CombatTextPage.lua
L["You may see other people's damage as your own."] = "Vous risquez de voir les dégâts des autres comme les vôtres."
L["Each text starts out looking like the one it's under. Changing one only changes that one."] = "Chaque texte a au départ l'apparence de celui au-dessus. En changer un ne change que celui-là."
L["Spells"] = "Sorts"
L["A look of their own for any of your spells."] = "Une apparence propre pour n'importe lequel de vos sorts."
L["Ours look the way the Look tab sets them. The game's look as they always do."] = "Les nôtres suivent l'onglet Apparence. Ceux du jeu restent comme d'habitude."
L["The game's own numbers, the way it normally draws them."] = "Les chiffres du jeu, comme il les affiche d'habitude."
L["Set XP and other floating text to The game's first. While it's on None, the game draws none of its numbers."] = "Réglez d'abord XP et autre texte flottant sur Celui du jeu. Tant qu'il est sur Aucune, le jeu n'affiche aucun de ses chiffres."
L["Ours when you're solo. In a group or raid, the game's own, which show every pet hit."] = "Les nôtres en solo. En groupe ou en raid, ceux du jeu, qui montrent chaque coup du familier."
L["In a group, ours only show your pet's spells, since its swings look the same as everyone else's. The game's shows every pet hit in its own look."] = "En groupe, les nôtres ne montrent que les sorts de votre familier, car ses coups de base ressemblent à ceux de tout le monde. Celui du jeu montre chaque coup du familier avec sa propre apparence."
L["Hides all the game's floating text, damage numbers included. Log out and back in to apply."] = "Masque tout le texte flottant du jeu, chiffres de dégâts compris. Déconnectez-vous puis reconnectez-vous pour appliquer."
L["Log out and back in to apply. With it hidden the game draws none of its numbers, so The game's is grayed out in the rows above."] = "Déconnectez-vous puis reconnectez-vous pour appliquer. Masqué, le jeu n'affiche aucun de ses chiffres, donc Celui du jeu est grisé dans les lignes du dessus."
L["Log out and back in to apply: until then the game's floating text stays hidden."] = "Déconnectez-vous puis reconnectez-vous pour appliquer : d'ici là, le texte flottant du jeu reste masqué."
L["None hides all of the game's floating text, damage numbers included. It takes a log out and back in."] = "Aucune masque tout le texte flottant du jeu, chiffres de dégâts compris. Il faut se déconnecter puis se reconnecter."
L["Each row sets many texts at once. You can change any of them afterward in the table below."] = "Chaque ligne règle plusieurs textes d'un coup. Vous pouvez les changer ensuite dans le tableau ci-dessous."
L["Shows only your crits and misses, with plain hits and heals turned off."] = "N'affiche que vos critiques et échecs, sans les coups et soins normaux."
L["Plain hits and heals are off and crits and misses are on. Switch any of them back in the table."] = "Coups et soins normaux désactivés, critiques et échecs activés. Vous pouvez tout remettre dans le tableau."
L["Turns off your auto attacks, along with their crits and misses."] = "Désactive vos attaques automatiques, avec leurs critiques et échecs."
L["Crits and your casts show in the middle, and the rest move aside."] = "Les critiques et vos sorts s'affichent au centre, et le reste se pousse sur le côté."
L["Your pet's hits show smaller than yours."] = "Les coups de votre familier s'affichent plus petits que les vôtres."
L["Your pet's hits show as big as yours."] = "Les coups de votre familier s'affichent aussi gros que les vôtres."
L["Every number is three quarters of the game's size."] = "Chaque chiffre fait les trois quarts de la taille du jeu."
L["Swings are smaller, and spells and heals get bigger the longer their cast."] = "Les coups de base sont plus petits, et les sorts et soins grossissent selon la durée de leur incantation."
L["Every number stays three quarters as long as the game's."] = "Chaque chiffre reste les trois quarts du temps du jeu."
L["Swings stay up for less time, and spells and heals stay longer the longer their cast."] = "Les coups de base restent moins longtemps, et les sorts et soins restent plus longtemps selon la durée de leur incantation."
L["Puts everything on this tab back to its defaults."] = "Remet tout cet onglet par défaut."
L["How big it is compared to the game's."] = "Sa taille par rapport à celle du jeu."
L["How big its crits are compared to its hits."] = "La taille de ses critiques par rapport à ses coups."
L["Adds (Glancing), (Blocked) or (Resisted) after the number. In a fight, the amount is hidden."] = "Ajoute (Érafle), (Bloqué) ou (Résisté) après le chiffre. En combat, la valeur est masquée."
L["How far it moves compared to the game's."] = "La distance qu'il parcourt par rapport à celui du jeu."
L["How long it stays compared to the game's."] = "Combien de temps il reste par rapport à celui du jeu."
L["How far into its time on screen it starts to fade."] = "À quel moment de son passage à l'écran il commence à s'estomper."
L["Grows big for a moment, then settles, like the game's crits."] = "Grossit un instant puis se pose, comme les critiques du jeu."
L["Shows or hides it. Turning it off hides the texts under it too, except crits, which have their own."] = "L'affiche ou le masque. Le désactiver masque aussi les textes en dessous, sauf les critiques, qui ont le leur."
L["This text's own look, on top of the one above it."] = "L'apparence propre de ce texte, en plus de celle du dessus."
L["Your own word in place of the game's (%s). Leave it empty to use the game's."] = "Votre propre mot à la place de celui du jeu (%s). Laissez vide pour garder celui du jeu."

-- Style/CombatTextSpells.lua
L["Spells and abilities"] = "Sorts et techniques"
L["Same look"] = "Même apparence"
L["Your spells"] = "Vos sorts"
L["Each spell starts out looking like its school on the Look tab. Change only what you want."] = "Chaque sort a au départ l'apparence de son école dans l'onglet Apparence. Changez seulement ce que vous voulez."
L["+ Add a spell"] = "+ Ajouter un sort"
L["Add a spell"] = "Ajouter un sort"
L["Lists the spells you've hit with, then the rest of your spellbook."] = "Liste les sorts avec lesquels vous avez frappé, puis le reste de votre grimoire."
L["Find a spell"] = "Chercher un sort"
L["Shows only the spells whose name has this in it. Press Enter to add a spell by its name."] = "N'affiche que les sorts dont le nom contient ceci. Appuyez sur Entrée pour ajouter un sort par son nom."
L["Every spell on the list."] = "Tous les sorts de la liste."
L["Changed"] = "Modifiés"
L["Only spells with a look of their own."] = "Seulement les sorts avec leur propre apparence."
L["Puts every spell's look back to its school's. The list stays."] = "Remet l'apparence de chaque sort à celle de son école. La liste reste."
L["Crits"] = "Critiques"
L["Ticks"] = "Tics"
L["No spells yet. Click + Add a spell to give one a look of its own."] = "Pas encore de sorts. Cliquez sur + Ajouter un sort pour en personnaliser un."
L["As its hits"] = "Comme ses coups"
L["This spell"] = "Ce sort"
L["Clear this spell"] = "Effacer ce sort"
L["Its crits"] = "Ses critiques"
L["Its crits' color"] = "Couleur des critiques"
L["Its ticks"] = "Ses tics"
L["Its ticks look like its hits."] = "Ses tics ressemblent à ses coups."
L["Its ticks are three quarters of its hits' size."] = "Ses tics font les trois quarts de la taille de ses coups."
L["Shows this spell's numbers or not."] = "Affiche ou non les chiffres de ce sort."
L["Its color. Right-click: its school's again."] = "Sa couleur. Clic droit : de nouveau celle de son école."
L["How big its numbers are. Right-click: its school's again."] = "La taille de ses chiffres. Clic droit : de nouveau celle de son école."
L["Its crits' color: its color unless set. Right-click: its color again."] = "La couleur de ses critiques : sa couleur, sauf si vous en choisissez une. Clic droit : de nouveau sa couleur."
L["Its ticks (a DoT's, a channel's): the same as its hits, or smaller."] = "Ses tics (d'un DoT, d'une canalisation) : comme ses coups, ou plus petits."
L["More..."] = "Plus..."
L["Every part of its look: its font, place and motion too."] = "Toute son apparence : sa police, sa place et son mouvement aussi."
L["Takes it off the list. Its numbers look like its school's again."] = "L'enlève de la liste. Ses chiffres reprennent l'apparence de son école."
L["Same"] = "Pareil"
L["Off on the Look tab"] = "Désactivé dans Apparence"
L["No spells match."] = "Aucun sort ne correspond."
L["%d spells, %d with a look of their own"] = "%d sorts, dont %d avec leur propre apparence"
L["Search your spells"] = "Chercher dans vos sorts"
L["Your spells that hit (this character)"] = "Vos sorts qui ont frappé (ce personnage)"
L["Other spells in your spellbook"] = "Autres sorts de votre grimoire"
L["Not seen yet"] = "Pas encore vu"
L["In the list"] = "Dans la liste"
L["%d hits"] = "%d coups"
L["No spells found."] = "Aucun sort trouvé."

-- Style/InterfaceRecolor.lua
L["Uses General's bar texture for progress bars, and the theme's color for the fold buttons."] = "Utilise la texture de barre de Général pour les barres de progression, et la couleur du thème pour les boutons de repli."
L["Uses General's bar texture for its bars, each in its own color."] = "Utilise la texture de barre de Général pour ses barres, chacune dans sa couleur."
L["Uses General's text font for its names and numbers."] = "Utilise la police de texte de Général pour ses noms et chiffres."
L["Uses General's bar texture for the bars' fill, with each weapon in its own color."] = "Utilise la texture de barre de Général pour le remplissage des barres, chaque arme dans sa couleur."
L["Uses General's text font for the bars' text."] = "Utilise la police de texte de Général pour le texte des barres."
L["Uses General's text font for their numbers."] = "Utilise la police de texte de Général pour leurs chiffres."

-- Style/LetterboxStyle.lua
L["Preview:"] = "Aperçu :"
L["The weather the Preview shows."] = "La météo que montre l'Aperçu."
L["Shows this weather's tint at its heaviest for a few seconds (at 50% while Strength is Off)."] = "Affiche la teinte de cette météo au plus fort pendant quelques secondes (à 50 % tant qu'Intensité est sur Désactivé)."
L["On the screen"] = "À l'écran"
L["Shows it for a few seconds, in CineMode or not (at 50% while it's Off)."] = "L'affiche quelques secondes, en CineMode ou non (à 50 % tant qu'il est sur Désactivé)."
L["Heavier weather"] = "Météo plus forte"
L["Medium"] = "Moyenne"
L["Heavy"] = "Forte"
L["Makes the game's own rain and snow thicker while its row is on, and puts yours back after."] = "Rend la pluie et la neige du jeu plus épaisses tant que sa ligne est active, puis remet votre réglage après."
L["Pulls the view distance in as a downpour would, for a few seconds."] = "Réduit la distance de vue comme une grosse averse, pendant quelques secondes."
L["The world"] = "Le monde"
L["Draw the world between the bars"] = "Afficher le monde entre les bandes"
L["Shows the whole view between the bars instead of hiding its top and bottom (it changes only out of fights)."] = "Affiche toute la vue entre les bandes au lieu d'en cacher le haut et le bas (ne change que hors combat)."
L["Shows the whole time in CineMode, including fights and the Calm Timer after them."] = "S'affiche tout le temps en CineMode, combats et Minuteur de calme compris."
L["When on, the bars look the way this page sets them. When off, they're Cinematic's plain black bars."] = "Activé, les bandes ont l'apparence réglée sur cette page. Désactivé, ce sont les simples bandes noires de Cinematic."
L["Takes the bars out and brings them back in, like at the start and end of a fight."] = "Fait partir les bandes puis les fait revenir, comme au début et à la fin d'un combat."
L["Shapes the space between the bars like a movie screen, on any monitor."] = "Donne à l'espace entre les bandes la forme d'un écran de cinéma, sur n'importe quel moniteur."
L["How tall the top bar is, as a share of the screen's height."] = "La hauteur de la bande du haut, en part de la hauteur de l'écran."
L["Click to link or unlink the two bars. Linked, they're the same height."] = "Cliquez pour lier ou délier les deux bandes. Liées, elles ont la même hauteur."
L["How tall the bottom bar is, as a share of the screen's height."] = "La hauteur de la bande du bas, en part de la hauteur de l'écran."
L["How long the bars take to come in or go. Set to 0 to match the UI's fade."] = "Combien de temps les bandes mettent à arriver ou partir. Réglez sur 0 pour suivre le fondu de l'interface."
L["How the weather tints the scene: a color for each weather, and how fast it comes in and goes."] = "Comment la météo teinte la scène : une couleur par météo, et la vitesse à laquelle elle arrive et repart."
L["When on, the weather uses the colors and time set here. When off, Cinematic's own."] = "Activé, la météo utilise les couleurs et la durée réglées ici. Désactivé, celles de Cinematic."
L["Pick this weather's tint. White is no change; darker colors darken the scene more."] = "Choisissez la teinte de cette météo. Le blanc ne change rien ; plus la couleur est sombre, plus la scène s'assombrit."
L["How long the weather's tint takes to come in as it starts, or to go as it clears or you step inside."] = "Combien de temps la teinte de la météo met à arriver quand elle commence, ou à partir quand le ciel se dégage ou que vous rentrez."

-- Style/MinimapStyle.lua
L["Minimap Style"] = "Style de la minicarte"
L["How the minimap looks: its shape, border and ring."] = "L'apparence de la minicarte : sa forme, sa bordure et son anneau."
L["Turns this page's minimap look on or off."] = "Active ou désactive l'apparence de minicarte de cette page."
L["Size and shape"] = "Taille et forme"
L["How big the minimap is."] = "La taille de la minicarte."
L["Makes the minimap square."] = "Rend la minicarte carrée."
L["Border size"] = "Taille de la bordure"
L["How thick the border round the square minimap is. 0: no border."] = "L'épaisseur de la bordure autour de la minicarte carrée. 0 : pas de bordure."
L["Border color:"] = "Couleur de bordure :"
L["Theme uses your theme's ring color, or black when it has none."] = "Thème prend la couleur d'anneau de votre thème, ou du noir s'il n'en a pas."
L["Zone name and clock inside"] = "Zone et horloge dedans"
L["Puts the zone name at the top of the square minimap and the clock in its corner."] = "Met le nom de la zone en haut de la minicarte carrée et l'horloge dans son coin."
L["Zoom buttons"] = "Boutons de zoom"
L["Hides the minimap's zoom buttons."] = "Masque les boutons de zoom de la minicarte."
L["Hides the zone name bar over the minimap."] = "Masque la barre du nom de la zone au-dessus de la minicarte."
L["Hides the day and night dial on the minimap's edge."] = "Masque le cadran jour et nuit sur le bord de la minicarte."
L["Ring and buttons"] = "Anneau et boutons"
L["Colors the rings around minimap buttons in your theme's ring color, or the border color when it has none."] = "Colore les anneaux des boutons de la minicarte avec la couleur d'anneau de votre thème, ou celle de la bordure s'il n'en a pas."
L["A little shading just inside the ring, so the map looks set into it."] = "Une petite ombre juste à l'intérieur de l'anneau, pour que la carte semble encastrée."
L["Zone bar in the theme's look"] = "Barre de zone aux couleurs du thème"
L["Shade and the zone bar's look come with themes that have a ring color."] = "L'ombre et l'apparence de la barre de zone viennent avec les thèmes qui ont une couleur d'anneau."

-- Style/PersonalStyle.lua
L["When on, the bars look the way this page sets them. When off, they use the game's own look."] = "Activé, les barres ont l'apparence réglée sur cette page. Désactivé, elles gardent celle du jeu."
L["It fades to a darker shade of its own color."] = "Elle tire vers une teinte plus sombre de sa propre couleur."
L["Its width in screen pixels, so the same number gives two bars the same width."] = "Sa largeur en pixels d'écran : le même nombre donne la même largeur à deux barres."
L["The health bar's width, growing out from its middle."] = "La largeur de la barre de vie, qui s'élargit depuis son centre."
L["The power bar's width, growing out from its middle."] = "La largeur de la barre de puissance, qui s'élargit depuis son centre."
L["The mana bar's width as a percent of the game's power bar, growing out from its middle."] = "La largeur de la barre de mana en pourcentage de la barre de puissance du jeu, qui s'élargit depuis son centre."
L["The health bar's height compared to the game's."] = "La hauteur de la barre de vie par rapport à celle du jeu."
L["The power bar's height compared to the game's."] = "La hauteur de la barre de puissance par rapport à celle du jeu."
L["How big your class resource is compared to the game's size."] = "La taille de votre ressource de classe par rapport à celle du jeu."
L["The mana bar's height compared to the power bar's."] = "La hauteur de la barre de mana par rapport à la barre de puissance."
L["The bars' border: the game's or one of ours. Custom sets its thickness and color below."] = "La bordure des barres : celle du jeu ou l'une des nôtres. Personnalisé règle son épaisseur et sa couleur ci-dessous."

-- Style/PlateCastStyle.lua
L["When on, the cast bars look the way this page sets them. When off, they use the game's own look."] = "Activé, les barres d'incantation ont l'apparence réglée sur cette page. Désactivé, elles gardent celle du jeu."
L["Makes it part of the unit frame, with its fill, border and font, right under its bars."] = "L'intègre au cadre d'unité, avec son remplissage, sa bordure et sa police, juste sous ses barres."
L["Pick the color of an interrupted cast. The game doesn't report this in every fight."] = "Choisissez la couleur d'une incantation interrompue. Le jeu ne l'indique pas dans tous les combats."
L["How dark it is behind the fill. This only works with a fill of your own; the game's keeps its own."] = "À quel point c'est sombre derrière le remplissage. Ne marche qu'avec votre propre remplissage ; celui du jeu garde le sien."
L["Its width compared to the game's, growing out from its middle. Nameplates only."] = "Sa largeur par rapport à celle du jeu, qui s'élargit depuis son centre. Barres de nom seulement."
L["The cast bar's height compared to the game's."] = "La hauteur de la barre d'incantation par rapport à celle du jeu."
L["The icon's size compared to the game's."] = "La taille de l'icône par rapport à celle du jeu."
L["A dark shadow behind the letters, down and to the right."] = "Une ombre sombre derrière les lettres, en bas à droite."
L["The look every cast bar uses while its row is set to Default."] = "L'apparence de chaque barre d'incantation tant que sa ligne est sur Défaut."
L["Default's (Cast Bars)"] = "Celle de Défaut (Barres d'incantation)"

-- Style/QuestItemStyle.lua
L["When on, the button looks the way this page sets it. When off, it looks like the game's extra ability button."] = "Activé, le bouton a l'apparence réglée sur cette page. Désactivé, il ressemble au bouton de technique supplémentaire du jeu."
L["Icons have their own dark border. Zooming in a little cuts it off."] = "Les icônes ont leur propre bordure sombre. Zoomer un peu la coupe."
L["A black border around its numbers."] = "Un contour noir autour de ses chiffres."

-- Style/QuestTalkStyle.lua
L["When on, the dialogue looks the way this page sets it. When off, it uses the game's parchment."] = "Activé, le dialogue a l'apparence réglée sur cette page. Désactivé, il garde le parchemin du jeu."
L["The size of the bubble and the reply list. Their text grows with them."] = "La taille de la bulle et de la liste des réponses. Leur texte grandit avec."
L["A black border around the letters, for light text with no panel behind it."] = "Un contour noir autour des lettres, pour un texte clair sans panneau derrière."
L["The bubble's text in a color of your own. The quest card keeps its own color."] = "Le texte de la bulle dans la couleur de votre choix. La carte de quête garde la sienne."

-- Style/RaidStyle.lua
L["When on, the raid frames look the way this page sets them. When off, they use the game's own look."] = "Activé, les cadres de raid ont l'apparence réglée sur cette page. Désactivé, ils gardent celle du jeu."
L["Uses the color below at full health, shifting to the At half and Empty colors as health drops."] = "Utilise la couleur ci-dessous en pleine santé, puis passe aux couleurs À moitié et Vide quand la vie baisse."
L["Tints the game's background a color of your own, picked below."] = "Teinte le fond du jeu dans une couleur de votre choix, ci-dessous."
L["The name's size compared to the game's."] = "La taille du nom par rapport à celle du jeu."
L["The look every group uses while its row is set to Same as the Default row."] = "L'apparence de chaque groupe tant que sa ligne est sur Comme la ligne Défaut."

-- Style/RollStyle.lua
L["When on, the window looks the way this page sets it. When off, it uses Roll Vision's usual look."] = "Activé, la fenêtre a l'apparence réglée sur cette page. Désactivé, elle garde l'apparence habituelle de Roll Vision."
L["A dark panel with a thin line around it, in the item's quality color."] = "Un panneau sombre entouré d'un fin trait, à la couleur de qualité de l'objet."

