L["Shows the line only this long at the start and end. All the way left (Off) shows it the whole way."] = "N'affiche le trait que pendant ce temps au début et à la fin. Tout à gauche (Désactivé), il reste tout du long."

-- Visions/CombatSoundRules.lua
L["How loud the sounds are, compared to your sound effects volume."] = "Le volume des sons, par rapport à votre volume des effets sonores."
L["This sound's volume, compared to the others."] = "Le volume de ce son, par rapport aux autres."
L["Resets this card's rules to the defaults."] = "Remet les règles de cette carte par défaut."
L["Resets this tab to its default rules: one sound as any other fight starts and one as it ends."] = "Remet les règles par défaut de cet onglet : un son au début de tout autre combat et un à la fin."

-- Visions/DamageVision.lua
L["Shows in every fight, wherever you are, so the other columns don't matter."] = "S'affiche dans chaque combat, où que vous soyez, les autres colonnes ne comptent donc pas."
L["Shows how you did on that boss as it dies."] = "Montre comment vous vous en êtes sorti sur ce boss quand il meurt."
L["Shows how you did on the whole run once it's done."] = "Montre comment vous vous en êtes sorti sur toute l'expédition une fois terminée."
L["Shows the recap card with the meter's whole run if you have one, or a made-up one if not (Stop hides it)."] = "Affiche la carte récap avec toute l'expédition de votre compteur si vous en avez un, ou une inventée sinon (Arrêter la masque)."
L["Shows your place over it (#2)."] = "Affiche votre place au-dessus (#2)."
L["A crown pops in as you take #1."] = "Une couronne apparaît quand vous passez #1."
L["Shows the name of the one you race, in their class's color."] = "Affiche le nom de votre rival, à la couleur de sa classe."
L["Shows your damage (or healing) so far."] = "Affiche vos dégâts (ou soins) jusqu'ici."
L["Shows each player's name on their row."] = "Affiche le nom de chaque joueur sur sa ligne."
L["Amber while you're behind, teal once you lead, or two colors of your own."] = "Ambre quand vous êtes derrière, bleu-vert une fois devant, ou deux couleurs de votre choix."

-- Visions/EmoteVision.lua
L["Emote Vision test: you'd %s."] = "Test d'Emote Vision : vous feriez %s."
L["Turn it on and pick which moments show a card, and the emotes on each."] = "Activez-le et choisissez quels moments affichent une carte, et les emotes de chacun."
L["Cards that need the other player's nameplate. CineMode keeps it for them."] = "Les cartes qui ont besoin de la barre de nom de l'autre joueur. Le CineMode la garde pour elles."
L["Puts the menu's emotes back to the defaults."] = "Remet par défaut les emotes du menu."
L["Shows wherever you are, but never in a fight. A card that comes up in a fight waits for it to end."] = "S'affiche où que vous soyez, mais jamais en combat. Une carte qui arrive en combat attend la fin."
L["Puts every moment's emotes back to the defaults."] = "Remet par défaut les emotes de chaque moment."
L["Only buffs from strangers bring up a card, not buffs from your party or raid."] = "Seules les améliorations d'inconnus font apparaître une carte, pas celles de votre groupe ou raid."

-- Page names and lists
L["A Minimap page in the Style hub: make the minimap square with a border in your theme's color, change its size, and hide its zoom buttons, zone bar or day and night dial."] = "Une page Minicarte dans la section Style : rendez la minicarte carrée avec une bordure aux couleurs de votre thème, changez sa taille, et masquez ses boutons de zoom, sa barre de zone ou son cadran jour et nuit."
L["A boss down in a dungeon or raid with your group (each one, not just the last): the emotes go to everyone."] = "Un boss tombé en donjon ou en raid avec votre groupe (chacun, pas seulement le dernier) : les emotes vont à tout le monde."
L["A boss's name as a title card, as its fight starts or as you first target it or come near: on the screen, in a letterbox bar or low on the left like a film, with its dungeon and which boss it is. Its look has its own tab on Battle Vision's Style page."] = "Le nom d'un boss en carton-titre, au début du combat ou quand vous le ciblez ou approchez pour la première fois : à l'écran, dans une bande ou en bas à gauche comme dans un film, avec son donjon et le numéro du boss. Son apparence a son propre onglet sur la page Style de Battle Vision."
L["A buff of a minute or more someone else puts on you (Fortitude, Arcane Intellect, a blessing...). Not heals over time."] = "Une amélioration d'une minute ou plus qu'un autre joueur vous lance (Robustesse, Intelligence des Arcanes, une bénédiction...). Pas les soins sur la durée."
L["A button on the inspect window opens the player's talents, and one on the talents window takes you back."] = "Un bouton dans la fenêtre d'inspection ouvre les talents du joueur, et un autre dans la fenêtre des talents vous ramène."
L["A calculator button on your talents window opens a talent planner that looks just like it, starting from your talents. Plan a build, see the level it needs, then copy it over to your talents window to apply."] = "Un bouton calculatrice dans votre fenêtre de talents ouvre un planificateur identique, qui part de vos talents. Préparez un build, voyez le niveau qu'il demande, puis copiez-le dans votre fenêtre de talents pour l'appliquer."
L["A cue as you go into a fight and come out of it: a word on the screen or in a letterbox bar, a pulse around the edges, an icon, and sounds you pick for each kind of fight, like horns for a raid boss. Its look has a page in the Style hub, with presets and a preview."] = "Un signal quand vous entrez en combat et en sortez : un mot à l'écran ou dans une bande, une pulsation sur les bords, une icône, et des sons au choix pour chaque type de combat, comme des cors pour un boss de raid. Son apparence a une page dans la section Style, avec des préréglages et un aperçu."
L["A grid that shows or hides each part of the nameplates in CineMode: health bar, name, cast bar, buffs, level and more."] = "Une grille qui affiche ou masque chaque élément des barres de nom en CineMode : barre de vie, nom, barre d'incantation, améliorations, niveau et plus."
L["A mark on your target's nameplate for when no target frame shows who you've got: an arrow, chevron, glow or brackets, colored by how they see you."] = "Une marque sur la barre de nom de votre cible quand aucun cadre de cible ne montre qui vous visez : flèche, chevron, lueur ou crochets, colorés selon ce qu'elle pense de vous."
L["A new Retail profile gives WoW Forever retail's look: Cinematic's own Edit Mode layout, with action bars 1 to 3, the micro menu and bags, and the XP bar each coming up on its own. Switch back to Default and your own layout returns."] = "Un nouveau profil Retail donne à WoW Forever l'allure de Retail : la disposition de mode Édition de Cinematic, avec les barres d'action 1 à 3, le micro-menu et les sacs, et la barre d'XP qui apparaissent chacun de leur côté. Revenez sur Défaut et votre disposition revient."
L["A new Spells tab on Combat Text Style gives any of your spells its own color, size and look, its crits and DoT ticks too."] = "Un nouvel onglet Sorts dans le style du texte de combat donne à n'importe lequel de vos sorts sa propre couleur, taille et apparence, critiques et tics de DoT compris."
L["A new Vision for the words that fade in on your screen between fights: what you did last time as you log in (\"Last time: Darkshore · 3 quests done · reached level 24\"), the time of day, a place under attack, and the death banner, each with its own tick and a Test button. Combat Vision is now called Battle Vision."] = "Une nouvelle Vision pour les mots qui apparaissent à l'écran entre les combats : ce que vous avez fait la dernière fois en vous connectant (\"La dernière fois : Sombrivage · 3 quêtes faites · niveau 24 atteint\"), le moment de la journée, un lieu attaqué et la bannière de mort, chacun avec sa case et un bouton Tester. Combat Vision s'appelle maintenant Battle Vision."
L["A new Wheels page shows every wheel and its icons, with its keybind right there, and lets you pick which wheels sit on the master wheel and in what order."] = "Une nouvelle page Roues montre chaque roue et ses icônes, avec son raccourci juste à côté, et vous laisse choisir quelles roues vont sur la roue principale et dans quel ordre."
L["A new page in the Community hub with links to the Discord, YouTube, CurseForge and GitHub, ready to copy."] = "Une nouvelle page dans la section Communauté, avec les liens Discord, YouTube, CurseForge et GitHub, prêts à copier."
L["A new rule editor"] = "Un nouvel éditeur de règles"
L["A place new to you: a zone the first time you're there, a subzone as the game says you discovered it, a dungeon or raid the first time you go in. In place of the Zone or Subzone card."] = "Un lieu nouveau pour vous : une zone la première fois que vous y êtes, une sous-zone quand le jeu dit que vous l'avez découverte, un donjon ou un raid la première fois que vous y entrez. À la place de la carte Zone ou Sous-zone."
L["A track with you above it and your rival below; the gap between you in color."] = "Une piste avec vous au-dessus et votre rival en dessous ; l'écart entre vous en couleur."
L["After an update with new features, a line in chat at login says so, with a link to What's new. Turn it off on the Chat page."] = "Après une mise à jour avec des nouveautés, une ligne dans le chat vous le dit à la connexion, avec un lien vers Nouveautés. Désactivez-la sur la page Chat."
L["An over-the-shoulder camera: you sit to one side of the screen and stay there as you zoom. Swap shoulders with a key, turn toward the NPCs you talk to and the enemies you target, and let your cast bar and resources slide along with you."] = "Une caméra par-dessus l'épaule : vous êtes d'un côté de l'écran et vous y restez en zoomant. Changez d'épaule avec une touche, tournez-vous vers les PNJ à qui vous parlez et les ennemis que vous ciblez, et laissez votre barre d'incantation et vos ressources glisser avec vous."
L["Arcane stars"] = "Étoiles arcaniques"
L["As a dungeon's or raid's last boss goes down: its name, the time since you came in and how many times you died."] = "Quand le dernier boss d'un donjon ou d'un raid tombe : son nom, le temps passé depuis votre entrée et combien de fois vous êtes mort."
L["As you cast your Hearthstone, Astral Recall or a teleport, a portal opens around you in your class and spec's color, closing in as the cast fills, then the screen goes black as you're whisked away. It plays alongside the tele camera."] = "Quand vous lancez votre pierre de foyer, Rappel astral ou une téléportation, un portail s'ouvre autour de vous aux couleurs de votre classe et spécialisation, se resserre à mesure que l'incantation se remplit, puis l'écran devient noir quand vous êtes emporté. Ça se joue avec la caméra de téléportation."
L["As you come into an inn or a city (not at login, not in a fight): the place's name. The same place at most once every 10 minutes."] = "Quand vous entrez dans une auberge ou une ville (pas à la connexion, pas en combat) : le nom du lieu. Le même lieu au plus une fois toutes les 10 minutes."
L["As you reach a new level (after the fight, if you're in one): the level, the zone and how long it took this session. Max level at the cap."] = "Quand vous atteignez un nouveau niveau (après le combat, si vous êtes en combat) : le niveau, la zone et le temps que ça a pris pendant cette session. Niveau max une fois au plafond."
L["As you turn in a story quest (campaign, important or legendary) or a dungeon, raid or elite one: its title."] = "Quand vous rendez une quête d'histoire (campagne, importante ou légendaire) ou une quête de donjon, de raid ou élite : son titre."
L["As your health drops, dark edges creep in around the screen with art themed to your class and talents (blood, frost, fire...), a heartbeat that quickens and a flash on big hits, so you can tell how you're doing at a glance."] = "Quand votre vie baisse, des bords sombres envahissent l'écran avec une illustration liée à votre classe et vos talents (sang, givre, feu...), un battement de cœur qui s'accélère et un flash sur les gros coups, pour voir d'un coup d'œil où vous en êtes."
L["At an NPC"] = "Chez un PNJ"
L["BigWigs, TomTom, HealBot Continued and Titan Panel get rows of their own and fade with Cinematic. Platynator and Threat Plates nameplates fade in CineMode, and Prat 3.0's chat follows the Chat page."] = "BigWigs, TomTom, HealBot Continued et Titan Panel ont leurs propres lignes et s'estompent avec Cinematic. Les barres de nom de Platynator et Threat Plates s'estompent en CineMode, et le chat de Prat 3.0 suit la page Chat."
L["Blood mist"] = "Brume de sang"
L["Camera Modes and Camera Triggers are now one Cameras page: a row for each trigger (an emote, a campfire, going AFK, a flight...) with the camera it starts, its music and CineMode, and where it can start. Copy a row to give a trigger a different camera in other places."] = "Modes de caméra et Déclencheurs de caméra ne forment plus qu'une page Caméras : une ligne par déclencheur (une emote, un feu de camp, passer AFK, un vol...) avec la caméra qu'il lance, sa musique et le CineMode, et où il peut démarrer. Copiez une ligne pour donner une autre caméra à un déclencheur ailleurs."
L["Change any Vitals Vision theme's art, colors, sparks and heartbeat, or make themes of your own from one, and rename or delete them. Reset theme puts one of ours back as it comes."] = "Changez l'illustration, les couleurs, les étincelles et le battement de cœur de n'importe quel thème de Vitals Vision, ou créez vos propres thèmes à partir d'un autre, puis renommez-les ou supprimez-les. Réinitialiser le thème remet l'un des nôtres d'origine."
L["ClassicUI Forever's action bars, bar art and quest watch now fade with Cinematic, and come back when you hover them."] = "Les barres d'action, l'habillage des barres et le suivi de quêtes de ClassicUI Forever s'estompent maintenant avec Cinematic, et reviennent quand vous les survolez."
L["Click the star beside any settings page's search box to save that page, open at the tab you're on. Your favorites get their own line at the top of Cinematic's list."] = "Cliquez sur l'étoile à côté de la recherche de n'importe quelle page d'options pour garder cette page, ouverte sur l'onglet où vous êtes. Vos favoris ont leur propre ligne en haut de la liste de Cinematic."
L["Combat text by spell"] = "Texte de combat par sort"
L["Cooldown Manager grid"] = "Grille du gestionnaire de recharges"
L["Creeping shadow"] = "Ombre rampante"
L["Ctrl+Click an auction to see it on your character in a small dressing room beside the Auction House, which now stays open. Turn it on in Quality of Life."] = "Ctrl+clic sur une enchère pour l'essayer sur votre personnage dans une petite cabine d'essayage à côté de l'hôtel des ventes, qui reste maintenant ouvert. Activez-le dans Confort."
L["Dressing room at the Auction House"] = "Cabine d'essayage à l'hôtel des ventes"
L["Earth wisps"] = "Volutes de terre"
L["ElvUI's frames, Deadly Boss Mods' timer bars and RestedXP's guide window now fade in CineMode: ElvUI's following the Game Frames rows of the frames they replace, RestedXP's with the Quest tracker row."] = "Les cadres d'ElvUI, les barres de minuteur de Deadly Boss Mods et la fenêtre de guide de RestedXP s'estompent maintenant en CineMode : ceux d'ElvUI suivent les lignes Cadres du jeu des cadres qu'ils remplacent, celle de RestedXP la ligne Suivi des quêtes."
L["Embers"] = "Braises"
L["Every camera is now a script of steps (turn, zoom, sway, wait, follow...) on the new Scripts page in the Camera hub. Pick one to see how it moves, change its steps and settings there, or copy it to make a camera of your own."] = "Chaque caméra est maintenant un script d'étapes (tourner, zoomer, se balancer, attendre, suivre...) sur la nouvelle page Scripts de la section Caméra. Choisissez-en une pour voir comment elle bouge, modifiez ses étapes et réglages, ou copiez-la pour créer votre propre caméra."
L["Every grid now has the same row: Always, then Combat, Target and Location dropdowns, Roles and Edit. Edit turns a row into a rule, for AND, NOT, Cities and more, with a dot showing whether it's on right now. Chat bubbles, tooltips, effects, music and the cameras now say where they show instead of where they hide."] = "Chaque grille a maintenant la même ligne : Toujours, puis les menus Combat, Cible et Lieu, Rôles et Modifier. Modifier transforme une ligne en règle, pour AND, NOT, Villes et plus, avec un point qui montre si elle est active en ce moment. Les bulles de discussion, infobulles, effets, la musique et les caméras disent maintenant où ils s'affichent au lieu d'où ils se cachent."
L["Fel wisps"] = "Volutes gangrenées"
L["FlareUI's unit frames, resource bars, buffs, quest tracker, party and raid frames fade in CineMode, following the Game Frames rows of the frames they replace."] = "Les cadres d'unité, barres de ressources, améliorations, suivi des quêtes, cadres de groupe et de raid de FlareUI s'estompent en CineMode, en suivant les lignes Cadres du jeu des cadres qu'ils remplacent."
L["Frames Forever's unit frames follow the Game Frames rows of the frames they replace. ShamanPower's totem bar fades with the Totem bar row, and its cooldown bar gets a row of its own."] = "Les cadres d'unité de Frames Forever suivent les lignes Cadres du jeu des cadres qu'ils remplacent. La barre de totems de ShamanPower s'estompe avec la ligne Barre de totems, et sa barre de recharges a sa propre ligne."
L["Frost creeps in on the screen's edges in snow, rain runs down the lens, and lightning flashes with thunder in storms. Off to start with: turn each up on the Weather page."] = "Le givre envahit les bords de l'écran sous la neige, la pluie ruisselle sur l'objectif et les éclairs claquent avec le tonnerre dans les orages. Désactivé au départ : montez chacun sur la page Météo."
L["Gliding"] = "Vol plané"
L["Green wisps"] = "Volutes vertes"
L["Guidelime support"] = "Prise en charge de Guidelime"
L["Guidelime's guide window, its ongoing steps and its waypoint arrow get a row each, so you can hide the guide and keep the arrow pointing the way."] = "La fenêtre de guide de Guidelime, ses étapes en cours et sa flèche de destination ont chacune leur ligne, pour masquer le guide et garder la flèche qui montre le chemin."
L["Hold a key to bring up a wheel of raid markers and put one on your target, or drop a ground marker where you let go. A master wheel opens any of the wheels from one key. Set the keys on the Keybinds page."] = "Maintenez une touche pour faire apparaître une roue de marqueurs de raid et en mettre un sur votre cible, ou poser un marqueur au sol là où vous relâchez. Une roue principale ouvre n'importe quelle roue depuis une seule touche. Réglez les touches sur la page Raccourcis."
L["Hold a key to bring up a wheel of the visions and turn Heal, Quest, Duel or Roll Vision on or off, even in a fight. It's on the master wheel too, and each vision has a toggle key of its own on the Keybinds page."] = "Maintenez une touche pour faire apparaître une roue des Visions et activer ou désactiver Heal, Quest, Duel ou Roll Vision, même en combat. Elle est aussi sur la roue principale, et chaque Vision a sa propre touche sur la page Raccourcis."
L["In CineMode the two players in a duel near you get their nameplates, each duel with its own color border and class icons."] = "En CineMode, les deux joueurs d'un duel près de vous ont leurs barres de nom, chaque duel avec sa propre bordure colorée et ses icônes de classe."
L["In a group, a window shows each item being rolled on, with everyone's pick and roll and the winner on top, so you needn't read the rolls in chat. Turn it off in the Visions page."] = "En groupe, une fenêtre montre chaque objet en jeu, avec le choix et le jet de chacun et le gagnant en haut, plus besoin de lire les jets dans le chat. Désactivez-la sur la page Visions."
L["Instead of damage meter numbers, see your race with #1 (or your lead over #2) as a bar, a race track or a ladder, plus a recap of how you did after each boss and dungeon."] = "Au lieu des chiffres du compteur de dégâts, voyez votre course contre le #1 (ou votre avance sur le #2) en barre, en piste ou en classement, plus un récap de votre performance après chaque boss et donjon."
L["Interface, Camera and Quality of life hold their pages behind a row of icons, with one search box for all of them."] = "Interface, Caméra et Confort rangent leurs pages derrière une rangée d'icônes, avec une seule recherche pour toutes."
L["Jade wisps"] = "Volutes de jade"
L["Links to the guidebook, troubleshooting and the bug report form, how to send your log with /cine log, and the Profiler for a slow game, together in Community."] = "Les liens vers le guide, le dépannage et le formulaire de bug, comment envoyer votre journal avec /cine log, et le Profiler si le jeu rame, tout ça réuni dans Communauté."
L["Lore Forever's subtitles, floating player, new page note and pin card get rows of their own and fade with Cinematic. With Custom dialogue frames on, a Play button on the box with the NPC's words plays the quest's narration or stops it."] = "Les sous-titres, le lecteur flottant, la note de nouvelle page et la carte épinglée de Lore Forever ont leurs propres lignes et s'estompent avec Cinematic. Avec Cadres de dialogue personnalisés activé, un bouton Lecture sur la boîte des paroles du PNJ lance ou arrête la narration de la quête."
L["Make scenes, like dungeons in combat, and pick what each spell shows in each one, side by side in one grid. Tick several spells to set them at once, or copy one spell's row onto others."] = "Créez des scènes, comme les donjons en combat, et choisissez ce que chaque sort affiche dans chacune, côte à côte dans une seule grille. Cochez plusieurs sorts pour les régler d'un coup, ou copiez la ligne d'un sort sur d'autres."
L["Make your own camera scenes on the Scenes page: an emote, a spell, a buff, a place, a moment or a key can start one, and a scene can have several triggers. The built-in ones are grouped by camera and take triggers of yours too. On My Shots, set how a camera sways and zooms, and share either with a friend."] = "Créez vos propres scènes de caméra sur la page Scènes : une emote, un sort, une amélioration, un lieu, un moment ou une touche peut en lancer une, et une scène peut avoir plusieurs déclencheurs. Les scènes intégrées sont rangées par caméra et acceptent aussi vos déclencheurs. Dans Mes plans, réglez comment une caméra se balance et zoome, et partagez l'un ou l'autre avec un ami."
L["Marks and colors for your focus, the unit under the mouse and a target that's attacking you, not just your target, each with its own look, when it shows, and rows for just enemies or friends. Set them on the Style hub's Nameplates page."] = "Des marques et des couleurs pour votre focalisation, l'unité sous la souris et une cible qui vous attaque, pas seulement votre cible, chacune avec sa propre apparence, son moment d'affichage, et des lignes pour les ennemis ou les alliés seulement. Réglez-les sur la page Barres de nom de la section Style."
L["Mobs and NPCs you still need for a quest keep their nameplates up, with a golden ! on their plate and your target frame. Optionally, the quest object in front of you glows so it's easy to spot."] = "Les monstres et PNJ dont vous avez encore besoin pour une quête gardent leur barre de nom, avec un ! doré sur leur barre et votre cadre de cible. En option, l'objet de quête devant vous brille pour le repérer facilement."
L["Motes (class and spec)"] = "Particules (classe et spé)"
L["Motes of light"] = "Particules de lumière"
L["Nameplates have a hub of their own: which show, the new Icons page for class and role icons, and their looks. Each kind of plate can have its own parts, and each Nameplate Style row its own bar, border, name font and level box."] = "Les barres de nom ont leur propre section : lesquelles s'affichent, la nouvelle page Icônes pour les icônes de classe et de rôle, et leur apparence. Chaque type de barre peut avoir ses propres éléments, et chaque ligne de Style des barres de nom sa propre barre, bordure, police du nom et case de niveau."
L["Names kept up over faded nameplates in CineMode now look like the game's own names over heads: colored by who they are, and smaller further off."] = "Les noms gardés au-dessus des barres de nom estompées en CineMode ressemblent maintenant aux noms du jeu au-dessus des têtes : colorés selon qui ils sont, et plus petits de loin."
L["Naowh Forever's top bar now fades in CineMode (a row on the Addon Frames page), and its RestedXP guide window fades with the Quest tracker row."] = "La barre du haut de Naowh Forever s'estompe maintenant en CineMode (une ligne sur la page Cadres d'addons), et sa fenêtre de guide RestedXP s'estompe avec la ligne Suivi des quêtes."
L["Pick HD or SD for Cinematic's settings and windows on the main page: flat and dark, or the game's own look. Auto follows your client, and your Character Models setting on WoW Forever."] = "Choisissez HD ou SD pour les options et fenêtres de Cinematic sur la page principale : plat et sombre, ou l'apparence du jeu. Auto suit votre client, et votre réglage Modèles de personnage sur WoW Forever."
L["Pick how much Cinematic does, Subtle, Balanced or Cinema, then Customize changes one part at a time: your layout, camera, look, Visions, chat and sound."] = "Choisissez à quel point Cinematic intervient, Subtil, Équilibré ou Cinéma, puis Personnaliser change une partie à la fois : votre disposition, la caméra, l'apparence, les Visions, le chat et le son."
L["Pick which parts of your frame and the target and focus frames show (portrait, name, level, frame art) for you and each kind of unit, to keep just the bars."] = "Choisissez quels éléments de votre cadre et des cadres de cible et de focalisation s'affichent (portrait, nom, niveau, habillage) pour vous et chaque type d'unité, pour ne garder que les barres."
L["Plague wisps"] = "Volutes de peste"
L["Pretends you're auto-running: the auto-run camera runs for 30 seconds where you stand. Moving, or clicking Stop, ends it."] = "Fait comme si vous étiez en course auto : la caméra de course auto tourne 30 secondes là où vous êtes. Bouger, ou cliquer sur Arrêter, y met fin."
L["Pretends you're auto-walking: the RP walk camera runs for 30 seconds where you stand. Moving, or clicking Stop, ends it."] = "Fait comme si vous étiez en marche auto : la caméra de marche RP tourne 30 secondes là où vous êtes. Bouger, ou cliquer sur Arrêter, y met fin."
L["Rain"] = "Pluie"
L["Rain, snow and sandstorms have their own page in Atmosphere. Preview each one, and pick its color and how fast it comes in on the Style tab."] = "La pluie, la neige et les tempêtes de sable ont leur propre page dans Atmosphère. Voyez chacune en aperçu, et choisissez sa couleur et sa vitesse d'arrivée dans l'onglet Style."
L["Runs Chat Cam for 30 seconds with a made-up conversation between two speakers either side of you. Moving, or clicking Stop, ends it."] = "Lance la caméra de discussion 30 secondes avec une fausse conversation entre deux personnes de chaque côté de vous. Bouger, ou cliquer sur Arrêter, y met fin."
L["Runs the quest camera for 30 seconds as if you were talking to a quest giver in front of you. Moving, or clicking Stop, ends it."] = "Lance la caméra de quête 30 secondes comme si vous parliez à un donneur de quêtes devant vous. Bouger, ou cliquer sur Arrêter, y met fin."
L["Sea breeze"] = "Brise marine"
L["See how much of your computer's time Cinematic takes, as a graph of the last five minutes, and record a while of play to see which parts cost the most. If Cinematic feels slow, Copy report and send it to us."] = "Voyez combien de temps de votre ordinateur prend Cinematic, en graphique sur les cinq dernières minutes, et enregistrez un moment de jeu pour voir quelles parties coûtent le plus. Si Cinematic semble lent, Copier le rapport et envoyez-le-nous."
L["See your keyboard on screen with what every key does: its spell's icon, cooldown and count, or the command's name. Hold its key to peek, tap it to keep it up, or type /cine keys. Hold Shift, Ctrl or Alt to see those keys."] = "Voyez votre clavier à l'écran avec ce que fait chaque touche : l'icône de son sort, sa recharge et son nombre, ou le nom de la commande. Maintenez sa touche pour jeter un œil, appuyez une fois pour le garder, ou tapez /cine keys. Maintenez Maj, Ctrl ou Alt pour voir ces touches."
L["Share a wheel of yours as a line of text and import one from a friend, reading every command first. Icons now come from every icon the game has, like the macro window's, and you can add icons of your own to the marker and vision wheels."] = "Partagez une de vos roues en une ligne de texte et importez celle d'un ami, en lisant chaque commande avant. Les icônes viennent maintenant de toutes les icônes du jeu, comme dans la fenêtre des macros, et vous pouvez ajouter vos propres icônes aux roues des marqueurs et des Visions."
L["Shortly after the death camera starts: YOU DIED across the middle of the screen, \"wasted\" or words of your own. Only with the death camera on (the Die row on the Scenes page)."] = "Peu après le début de la caméra de mort : VOUS ÊTES MORT au milieu de l'écran, \"wasted\" ou vos propres mots. Seulement avec la caméra de mort activée (la ligne Mourir de la page Scènes)."
L["Shows a pretend card for each moment in turn (close the settings to see it). With someone targeted it's theirs, and its buttons really emote at them; with no one, they only say in chat what they'd do."] = "Affiche une fausse carte pour chaque moment, l'un après l'autre (fermez les options pour la voir). Avec quelqu'un en cible, c'est la sienne, et ses boutons font vraiment l'emote vers lui ; sans personne, ils disent seulement dans le chat ce qu'ils feraient."
L["Six new Vitals Vision themes are built from the game's own full-screen effects, moving and closing in as your health drops: Cosmic void, Hellfire, Radiance, Frostbite, Fel flames and Spellfire. Find them under More themes."] = "Six nouveaux thèmes de Vitals Vision faits avec les effets plein écran du jeu, qui bougent et se resserrent quand votre vie baisse : Vide cosmique, Flammes infernales, Rayonnement, Engelure, Gangreflammes et Feu-sorcier. Ils sont dans Plus de thèmes."
L["Someone from your guild (not in your group) comes into view: with friendly nameplates on, as soon as you see them; otherwise when you mouse over or target them. Once an hour per person."] = "Quelqu'un de votre guilde (pas dans votre groupe) apparaît : avec les barres de nom amicales activées, dès que vous le voyez ; sinon quand vous le survolez ou le ciblez. Une fois par heure et par personne."
L["Someone near you earns an achievement (a stranger, someone in your group or in your guild)."] = "Quelqu'un près de vous obtient un haut fait (un inconnu, quelqu'un de votre groupe ou de votre guilde)."
L["Someone you grouped with lately (the game's Recent Allies, not in your group now) comes into view: with friendly nameplates on, as soon as you see them; otherwise when you mouse over or target them. Once an hour per person."] = "Quelqu'un avec qui vous avez groupé récemment (les Alliés récents du jeu, pas dans votre groupe maintenant) apparaît : avec les barres de nom amicales activées, dès que vous le voyez ; sinon quand vous le survolez ou le ciblez. Une fois par heure et par personne."
L["Souls"] = "Âmes"
L["Spanish, German, French, Russian, Portuguese, Italian, Korean and Chinese, with a Language choice on the main page."] = "Espagnol, allemand, français, russe, portugais, italien, coréen et chinois, avec un choix de Langue sur la page principale."
L["Starlight"] = "Lumière d'étoiles"
L["Talking to an NPC, their words show in a speech bubble over their head and your replies in a list below, instead of the game's gossip and quest windows. Pick a reply with 1-9, and Space to read on."] = "Quand vous parlez à un PNJ, ses paroles s'affichent dans une bulle au-dessus de sa tête et vos réponses dans une liste en dessous, au lieu des fenêtres de dialogue et de quête du jeu. Choisissez une réponse avec 1-9, et Espace pour continuer."
L["The Addon Frames page's Find frames tab can look for other addons' frames that nothing fades, say which addon made each and guess which row it should follow. Add them with a click."] = "L'onglet Trouver des cadres de la page Cadres d'addons peut chercher les cadres d'autres addons que rien n'estompe, dire quel addon a fait chacun et deviner quelle ligne il devrait suivre. Ajoutez-les en un clic."
L["The Camera hub's General page now shows every camera, built in and yours, as an icon. Click one to open a tab with its script and the scenes that play it, and jump straight to either."] = "La page Général de la section Caméra montre maintenant chaque caméra, intégrée ou à vous, sous forme d'icône. Cliquez-en une pour ouvrir un onglet avec son script et les scènes qui la jouent, et y aller directement."
L["The Cards page has 13 new moments: level up, places discovered, flight arrivals, inns, achievements, reputation, new mounts and pets, profession ranks, story quests, dungeons cleared, rares, battlegrounds and kill streaks. Every card now belongs to one of four looks, so they match out of the box."] = "La page Cartes a 13 nouveaux moments : montée de niveau, lieux découverts, arrivées en vol, auberges, hauts faits, réputation, nouvelles montures et mascottes, rangs de métier, quêtes d'histoire, donjons terminés, rares, champs de bataille et séries de victimes. Chaque carte appartient maintenant à l'une de quatre apparences, pour qu'elles aillent ensemble d'emblée."
L["The UI fades and letterbox bars come in between fights. Combat, casting and opening windows bring it back."] = "L'interface s'estompe et des bandes arrivent entre les combats. Le combat, les incantations et l'ouverture de fenêtres la font revenir."
L["The faded minimap comes up when ore, herbs or treasure show on it, a quest of yours is done, or another icon appears, with a ping on the node if you like."] = "La minicarte estompée revient quand du minerai, des herbes ou un trésor y apparaissent, qu'une de vos quêtes est terminée, ou qu'une autre icône apparaît, avec un signal sur le point si vous voulez."
L["The first time you enter a zone like Westfall or Duskwood, its name slams onto the screen in huge white capitals. Comes with the new Headline style."] = "La première fois que vous entrez dans une zone comme la Marche de l'Ouest ou le Bois de la Pénombre, son nom s'abat sur l'écran en énormes capitales blanches. Arrive avec le nouveau style Gros titre."
L["The game's floating combat text about you (hits, heals, misses, power, auras, Low Health) now has a page of its own on Style: a look for each kind, beside your character, and it can follow the Shoulder Cam."] = "Le texte de combat flottant du jeu qui vous concerne (coups, soins, échecs, puissance, auras, vie basse) a maintenant sa propre page dans Style : une apparence par type, à côté de votre personnage, et il peut suivre la Caméra d'épaule."
L["The game's own graphics settings one by one, past what its Graphics menu allows: ground clutter, view distance and more."] = "Les réglages graphiques du jeu un par un, au-delà de ce que permet son menu Graphismes : végétation au sol, distance de vue et plus."
L["The game's windows open in the middle of the screen, can be dragged by their title bar and open where you last dropped them. The backpack too."] = "Les fenêtres du jeu s'ouvrent au milieu de l'écran, se déplacent par leur barre de titre et s'ouvrent là où vous les avez laissées. Le sac à dos aussi."
L["The minimap button glows while a vision is doing something, and its menu lists the visions in use with a link to each one's page."] = "Le bouton de la minicarte brille quand une Vision fait quelque chose, et son menu liste les Visions en cours avec un lien vers la page de chacune."
L["The names Cinematic draws on faded nameplates in CineMode have a page of their own: their colors, outline, opacity, size and height, with presets and a preview."] = "Les noms que Cinematic affiche sur les barres de nom estompées en CineMode ont leur propre page : couleurs, contour, opacité, taille et hauteur, avec des préréglages et un aperçu."
L["The rule editor is rebuilt: words in categories you can search, suggestions as you type, and a line that shows which parts of your rule are true where you stand."] = "L'éditeur de règles est refait : des mots rangés par catégories où chercher, des suggestions pendant que vous tapez, et une ligne qui montre quelles parties de votre règle sont vraies là où vous êtes."
L["Three new cards in the top bar: how much of a zone you've explored, an achievement with one step left, and an achievement's step done. Each shows at most once every 10 minutes; on in the Cinema profile."] = "Trois nouvelles cartes dans la barre du haut : combien d'une zone vous avez exploré, un haut fait à qui il ne reste qu'une étape, et une étape de haut fait accomplie. Chacune s'affiche au plus une fois toutes les 10 minutes ; actives dans le profil Cinéma."
L["Tick Copy chat button on the Quality of life page and a small icon in a chat window's corner opens its lines, ready to select and copy with Ctrl+C."] = "Cochez Bouton Copier le chat sur la page Confort, et une petite icône dans le coin d'une fenêtre de chat ouvre ses lignes, prêtes à sélectionner et copier avec Ctrl+C."
L["Tick Show speech from behind you on the Chat page and says and yells from people behind you or out of view show as bubbles low on the screen, rising up from below, instead of bringing up chat."] = "Cochez Afficher les paroles venant de derrière vous sur la page Chat, et ce que disent ou crient les gens derrière vous ou hors de vue s'affiche en bulles en bas de l'écran, qui montent depuis le bas, au lieu de faire apparaître le chat."
L["Type /cine find and a few words, or search in the settings, to get a list of every matching option; click one to go straight to it."] = "Tapez /cine find et quelques mots, ou cherchez dans les options, pour avoir la liste de toutes les options qui correspondent ; cliquez-en une pour y aller directement."
L["Type /cine why, or pick it from the minimap button's menu, then click any frame to see why it's showing or hidden right now and which settings say so. It works on other addons' frames, Cinematic's own (like quest talk), and the last tooltip too. The Why Is It Showing? page in Community lists every row of frames at once."] = "Tapez /cine why, ou choisissez-le dans le menu du bouton de la minicarte, puis cliquez sur n'importe quel cadre pour voir pourquoi il est affiché ou masqué en ce moment et quels réglages le disent. Ça marche sur les cadres des autres addons, ceux de Cinematic (comme les dialogues de quête), et la dernière infobulle aussi. La page Pourquoi est-ce affiché ? dans Communauté liste toutes les lignes de cadres d'un coup."
L["Type part of a frame's name, or of the addon that made it, to find frames to fade. Hover a match to see it marked on screen, then click it to fade it."] = "Tapez une partie du nom d'un cadre, ou de l'addon qui l'a fait, pour trouver des cadres à estomper. Survolez un résultat pour le voir marqué à l'écran, puis cliquez dessus pour l'estomper."
L["Valhalla"] = "Valhalla"
L["Venom wisps"] = "Volutes de venin"
L["Vitals Vision's themes now have spiral arms turning over the screen as your health drops, quicker the weaker you are. Set them on the Style page's new Swirl tab, or try the swirl themes under More themes: Vortex, Abyss and Dungeon portal."] = "Les thèmes de Vitals Vision ont maintenant des bras en spirale qui tournent sur l'écran quand votre vie baisse, plus vite à mesure que vous faiblissez. Réglez-les dans le nouvel onglet Tourbillon de la page Style, ou essayez les thèmes tourbillon dans Plus de thèmes : Vortex, Abysse et Portail de donjon."
L["Weather on the screen"] = "Météo à l'écran"
L["Weather page"] = "Page Météo"
L["Wheels of your own, up to 8: each icon on one runs a command when you pick it, such as /rw Pull in 10 or /readycheck (anything a macro can do, a line each), in a fight too. Give a wheel its own key here, or put it on the master wheel. They're the same for all your characters."] = "Vos propres roues, jusqu'à 8 : chaque icône lance une commande quand vous la choisissez, comme /rw Pull in 10 ou /readycheck (tout ce qu'une macro peut faire, une ligne chacune), même en combat. Donnez à une roue sa propre touche ici, ou mettez-la sur la roue principale. Elles sont les mêmes pour tous vos personnages."
L["When someone buffs you, raises you, emotes at you, summons you or trades with you, or your group kills a boss or levels up, a small card shows who it was, with emotes to answer in one click. Pick each moment's emotes (voice ones too) and one of six card styles."] = "Quand quelqu'un vous lance une amélioration, vous ressuscite, vous fait une emote, vous invoque ou échange avec vous, ou que votre groupe tue un boss ou monte de niveau, une petite carte montre qui c'était, avec des emotes pour répondre en un clic. Choisissez les emotes de chaque moment (vocales aussi) et l'un des six styles de carte."
L["When the LocalDefense channel says a place is under attack (\"Dun Algaz is under attack!\"), with your faction's city bell. The same place at most once every 90 seconds."] = "Quand le canal DéfenseLocale annonce qu'un lieu est attaqué (\"Dun Algaz est attaqué !\"), avec la cloche de la ville de votre faction. Le même lieu au plus une fois toutes les 90 secondes."
L["When the time of day changes during play (not in combat), its name with a fitting sound: a rooster at dawn, a horse in the morning, your faction's bell at midday, frogs in the evening, an owl at dusk and a wolf at night."] = "Quand le moment de la journée change en jeu (pas en combat), son nom avec un son qui va bien : un coq à l'aube, un cheval le matin, la cloche de votre faction à midi, des grenouilles le soir, une chouette au crépuscule et un loup la nuit."
L["Wisps"] = "Volutes"
L["Wisps (class and spec)"] = "Volutes (classe et spé)"
L["You and a stranger (not in your group or guild) target each other for 10 seconds straight. Once you've looked away, it can happen again."] = "Vous et un inconnu (ni dans votre groupe ni dans votre guilde) vous ciblez mutuellement pendant 10 secondes d'affilée. Une fois que vous avez regardé ailleurs, ça peut recommencer."
L["Your character lies down as if dead and the death camera runs for 30 seconds. Moving, or clicking Stop, ends it."] = "Votre personnage s'allonge comme s'il était mort et la caméra de mort tourne 30 secondes. Bouger, ou cliquer sur Arrêter, y met fin."
L["Your player frame, pet frame and resource display have a page of their own: kept up while you recover or run low on mana, and held back at the start of a fight until your power changes."] = "Vos cadres du joueur et du familier et votre affichage des ressources ont leur propre page : affichés pendant que vous récupérez ou manquez de mana, et retenus au début d'un combat jusqu'à ce que votre puissance change."
L["\"Dun Algaz is under attack!\" shows in red where the zone name appears, with your faction's city bell."] = "\"Dun Algaz est attaqué !\" s'affiche en rouge là où apparaît le nom de la zone, avec la cloche de la ville de votre faction."
L["combat"] = "combat"
